import { supabase } from './config.js';
const SESSION=JSON.parse(localStorage.getItem('bm_staff')||'{}');
const SHOP_ID=localStorage.getItem('shop_id');
const PERMS_STR=localStorage.getItem('bm_shop_perms');
if(!SHOP_ID && (!SESSION||!SESSION.staff_id)){window.location.replace('./login.html');throw new Error('Redirecting to login...')}
const IS_ADMIN=!SESSION.staff_id||SESSION.staff_id==='01'||SESSION.role==='Admin';
const CURRENT_STAFF=SESSION.staff_id||'01'; const CURRENT_NAME=SESSION.name||'Admin';
const SHOP_PERMS=JSON.parse(PERMS_STR||'{}');
const $=id=>document.getElementById(id);
const fmt=n=>'PKR '+Number(n||0).toLocaleString('en-PK',{maximumFractionDigits:0});
const esc=s=>(s??'').toString().replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bmNorm=v=>(v||'').toString().toLowerCase().replace(/\s+/g,' ').trim();
const bmTodayISO=()=>new Date().toISOString().slice(0,10);
const bmMoney=n=>Number(n||0);
function checkPermission(a){if(IS_ADMIN)return true;if(a==='edit'&&!SESSION.can_edit){toast('Edit permission nahi hai!','error');return false}if(a==='delete'&&!SESSION.can_delete){toast('Delete permission nahi hai!','error');return false}return true}
function toast(msg,type='info'){const h=$('toastHost');if(!h)return;const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;h.appendChild(el);setTimeout(()=>el.remove(),3800)}
async function logActivity(action,module,details=''){try{const{error}=await supabase.from('activity_log').insert({staff_id:CURRENT_STAFF,staff_name:CURRENT_NAME,action,module,details:String(details).slice(0,500)});if(error)console.warn('log',error.message)}catch(e){console.warn(e.message)}}
if($('userName'))$('userName').textContent=CURRENT_NAME||localStorage.getItem('owner_name')||'BM MOBILE ZONE';
if($('userRole'))$('userRole').textContent=(SESSION.role||'ADMIN').toUpperCase();
if($('welcomeName'))$('welcomeName').textContent=CURRENT_NAME;
if($('userAvatar'))$('userAvatar').textContent=(CURRENT_NAME||'B')[0].toUpperCase();
if($('todayDate'))$('todayDate').textContent=new Intl.DateTimeFormat('en-PK',{dateStyle:'full'}).format(new Date());
$('logoutBtn')?.addEventListener('click',()=>{if(!confirm('Logout karna hai?'))return;['bm_staff','shop_id','shop_name','owner_name','bm_held_carts','bm_shop_perms'].forEach(k=>localStorage.removeItem(k));window.location.replace('./login.html')});
// ---------- SHOP ----------
let SHOP={name:'BM MOBILE ZONE',address:'Chohan Mobile Market, Zafarwal',phone1:'0345-6613232',phone2:'0307-6613232',tagline:'Your Trusted Mobile Shop',tax_rate:0,tax_enabled:false};
async function loadShopSettings(){try{const{data}=await supabase.from('shop_settings').select('*').limit(1).maybeSingle();if(data)SHOP={name:data.shop_name||SHOP.name,address:data.address||SHOP.address,phone1:data.phone1||SHOP.phone1,phone2:data.phone2||SHOP.phone2,tagline:data.tagline||SHOP.tagline,tax_rate:Number(data.tax_rate||0),tax_enabled:data.tax_enabled===true}}catch(e){}}
let CATEGORIES=['Mobile Phones','Mobile Accessories','Chargers & Cables','Handsfree & Audio','Batteries','Memory & Storage','Mobile Parts','Covers','Tempered Glass','Repairing Tools'];
let BRANDS=['Samsung','Apple','Xiaomi','Oppo','Vivo','Infinix','Tecno','Nokia','Huawei','Realme','OnePlus','Other'];
let ALL_PRODUCTS=[],ALL_RACKS=[],ALL_CUSTOMERS=[],ALL_SUPPLIERS=[];
// ---------- PRINT ----------
function urduTermsBlock(type='sale'){const common=`<div>• براہِ کرم مال کاؤنٹر پر چیک کریں۔</div><div>• پھولی ہوئی بیٹری کی کوئی وارنٹی نہیں ہے۔</div><div>• بیٹری کی وارنٹی صرف 2 دن ہوگی۔</div><div>• استعمال شدہ Accessories واپس یا تبدیل نہیں ہوں گی۔</div>`;const saleExtra=`<div>• سیل شدہ مال واپس یا تبدیل نہیں ہوگا۔</div><div>• وارنٹی کے لیے رسید لازمی پیش کریں۔</div>`;const repairExtra=`<div>• موبائل مرمت کے بعد وصول کرنے کے لیے یہ رسید لازمی ساتھ لائیں۔</div><div>• مرمت شدہ موبائل کی وارنٹی صرف 7 دن ہوگی۔</div>`;return `<hr style="border-top:1px dashed #000;margin:6px 0"><div style="text-align:right;font-size:12px;direction:rtl;line-height:1.7">${type==='repair'?'<div style="text-align:center;font-weight:bold">مرمت کی شرائط</div>':''}${common}${type==='repair'?repairExtra:saleExtra}</div>`}
function printThermal80mm(data,type='sale'){const w=window.open('','_blank','width=340,height=680');if(!w)return toast('Popup blocked','error');let sub=Number(data.subtotal||0),tot=Number(data.total||0);const sum=(data.items||[]).reduce((s,it)=>s+Number(it.line_total||it.total||it.amount||0),0);if(!sub)sub=sum;if(!tot)tot=sub-Number(data.discount||0)+Number(data.tax||0);const rows=(data.items||[]).map(it=>`<tr><td style="text-align:left;font-size:11px">${esc(it.product_name||it.name||it.description)}<br><small>${it.quantity||1} x ${fmt(it.unit_price||it.price||0)}</small></td><td style="text-align:right;font-size:11px">${fmt(it.line_total||it.total||0)}</td></tr>`).join('');w.document.write(`<html><head><title>Receipt</title></head><body style="font-family:Arial;width:72mm;margin:0 auto;font-size:12px"><div style="text-align:center"><b style="font-size:16px">${esc(data.shop?.name||SHOP.name)}</b><br><small>${esc(data.shop?.address||SHOP.address)}<br>${esc(data.shop?.phone1||SHOP.phone1)} | ${esc(data.shop?.phone2||SHOP.phone2)}</small><hr></div><div>Invoice: <b>${esc(data.invoice||'')}</b><br>Customer: ${esc(data.customer||'Walk-in')}<br>Cashier: ${esc(data.cashier||CURRENT_NAME)}<br>Date: ${new Date(data.date||Date.now()).toLocaleString('en-PK')}</div><table style="width:100%;border-collapse:collapse;margin:8px 0">${rows}</table><hr><div style="display:flex;justify-content:space-between"><span>Subtotal</span><b>${fmt(sub)}</b></div><div style="display:flex;justify-content:space-between"><span>Discount</span><b>${fmt(data.discount||0)}</b></div><div style="display:flex;justify-content:space-between"><span>Tax</span><b>${fmt(data.tax||0)}</b></div><div style="display:flex;justify-content:space-between;font-size:14px"><span>Total</span><b>${fmt(tot)}</b></div><div style="display:flex;justify-content:space-between"><span>Paid</span><b>${fmt(data.paid||0)}</b></div><div style="display:flex;justify-content:space-between"><span>Balance (Udhar)</span><b>${fmt(data.balance||0)}</b></div><div>Method: ${esc(data.payment_method||'Cash')}</div>${urduTermsBlock(type)}<div style="text-align:center;margin-top:8px">*** Shukriya! ***</div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function printA4Premium(data,type='sale'){const w=window.open('','_blank','width=800,height=900');if(!w)return toast('Popup blocked','error');const rows=(data.items||[]).map((it,i)=>`<tr><td>${i+1}</td><td>${esc(it.product_name||it.name||it.description)}</td><td>${it.quantity||1}</td><td>${fmt(it.unit_price||it.price||0)}</td><td>${fmt(it.line_total||it.total||0)}</td></tr>`).join('');w.document.write(`<html><head><title>Invoice ${esc(data.invoice||'')}</title></head><body style="font-family:Arial;max-width:700px;margin:20px auto"><div style="display:flex;justify-content:space-between"><div><h2 style="margin:0">${esc(data.shop?.name||SHOP.name)}</h2><small>${esc(data.shop?.address||SHOP.address)}<br>${esc(data.shop?.phone1||SHOP.phone1)} | ${esc(data.shop?.phone2||SHOP.phone2)}</small></div><div style="text-align:right"><h3>INVOICE</h3>${esc(data.invoice||'')}<br>${new Date(data.date||Date.now()).toLocaleString('en-PK')}</div></div><hr><p>Customer: <b>${esc(data.customer||'Walk-in')}</b> | Phone: ${esc(data.phone||'—')} | Cashier: ${esc(data.cashier||CURRENT_NAME)} | Method: ${esc(data.payment_method||'Cash')}</p><table style="width:100%;border-collapse:collapse"><thead><tr><th>#</th><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table><hr><div style="text-align:right">Subtotal: ${fmt(data.subtotal||0)}<br>Discount: ${fmt(data.discount||0)}<br>Tax: ${fmt(data.tax||0)}<br><b>Total: ${fmt(data.total||0)}</b><br>Paid: ${fmt(data.paid||0)}<br><b>Balance: ${fmt(data.balance||0)}</b></div>${urduTermsBlock(type)}<script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
window.printThermal80mm=printThermal80mm;window.printA4Premium=printA4Premium;
// ---------- MODAL ----------
let MODAL_CONFIRM=null;
function openModal(title,body,onConfirm,confirmText='Save'){const bd=$('modalBackdrop');if(!bd)return;$('modalTitle').textContent=title;$('modalBody').innerHTML=body;MODAL_CONFIRM=onConfirm;$('modalConfirm').textContent=confirmText||'Save';bd.classList.add('open');attachEnterNavigation($('modalBody'));setTimeout(()=>{const f=$('modalBody').querySelector('input:not([type=hidden]):not([readonly]),select,textarea');f?.focus()},80)}
function closeModal(){const bd=$('modalBackdrop');if(bd)bd.classList.remove('open');MODAL_CONFIRM=null}
$('modalCancel')?.addEventListener('click',closeModal);
$('modalConfirm')?.addEventListener('click',async()=>{if(!MODAL_CONFIRM)return;const btn=$('modalConfirm');btn.disabled=true;try{await MODAL_CONFIRM()}catch(e){toast(e.message,'error')}finally{btn.disabled=false}});
// ---------- SIDEBAR / NAV ----------
const sidebar=$('mainSidebar'),handle=$('sidebarHandle');
handle?.addEventListener('click',e=>{e.stopPropagation();const o=sidebar.classList.toggle('show');handle.classList.toggle('open',o);if(o)setTimeout(()=>{sidebar.classList.remove('show');handle.classList.remove('open')},15000)});
document.addEventListener('click',e=>{if(sidebar&&handle&&!sidebar.contains(e.target)&&!handle.contains(e.target)){sidebar.classList.remove('show');handle.classList.remove('open')}});
const MODULE_TITLES={overview:'Dashboard',inventory:'Inventory',racks:'Racks',purchases:'Purchases / Products',sales:'Sales / POS',repairing:'Repairing',customers:'Customers',suppliers:'Suppliers',credit:'Credit / Udhar',expenses:'Expenses',reports:'Reports & P&L',transactions:'Transactions',settings:'Staff & Logs'};
const MODULE_KEYS={o:'overview',i:'inventory',k:'racks',u:'purchases',l:'sales',r:'repairing',c:'customers',s:'suppliers',d:'credit',e:'expenses',p:'reports',t:'transactions',',':'settings'};
function hasAccess(mod){const m={sales:'allow_pos',inventory:'allow_inventory',racks:'allow_inventory',purchases:'allow_purchases',repairing:'allow_repairing',customers:'allow_customers',suppliers:'allow_suppliers',credit:'allow_credit',expenses:'allow_expenses',reports:'allow_reports',transactions:'allow_transactions',settings:'allow_staff'};const k=m[mod];if(k&&SHOP_PERMS[k]===false)return false;return true}
function navTo(mod){if(!hasAccess(mod)){toast('Access Denied — is section ki permission nahi hai.','error');return}document.querySelectorAll('.nav-item[data-module]').forEach(b=>{const mm=b.dataset.module;if(mm&&!hasAccess(mm)&&mm!=='overview')b.style.display='none';else b.style.display='flex'});const btn=document.querySelector(`.nav-item[data-module="${mod}"]`);if(!btn)return;document.querySelectorAll('.nav-item').forEach(b=>b.classList.remove('active'));btn.classList.add('active');document.querySelectorAll('.module').forEach(m=>m.classList.remove('active'));const t=$('module-'+mod);if(t)t.classList.add('active');if($('pageTitle'))$('pageTitle').textContent=MODULE_TITLES[mod]||mod;document.body.dataset.module=mod;loadModule(mod);sidebar?.classList.remove('show');handle?.classList.remove('open');if(mod==='sales')setTimeout(focusPOS,120)}
document.querySelectorAll('.nav-item[data-module]').forEach(b=>b.addEventListener('click',()=>navTo(b.dataset.module)));
async function loadModule(mod){switch(mod){case 'overview':return loadOverview();case 'inventory':return loadInventory();case 'racks':return loadRacks();case 'purchases':return loadPurchasesModule();case 'sales':return loadSaleProducts();case 'repairing':return loadRepairs();case 'customers':return loadCustomers();case 'suppliers':return loadSuppliers();case 'credit':return loadCredit();case 'expenses':return loadExpenses();case 'transactions':return loadTransactions();case 'settings':return loadStaff();case 'reports':return runReport();}}
// ---------- THEME ----------
(function(){const s=localStorage.getItem('bm_theme');if(s==='dark')document.documentElement.setAttribute('data-theme','dark');const b=$('themeToggle');if(b){b.textContent=document.documentElement.getAttribute('data-theme')==='dark'?'☀️':'🌙';b.addEventListener('click',()=>{const d=document.documentElement.getAttribute('data-theme')==='dark';if(d){document.documentElement.removeAttribute('data-theme');localStorage.setItem('bm_theme','light');b.textContent='🌙'}else{document.documentElement.setAttribute('data-theme','dark');localStorage.setItem('bm_theme','dark');b.textContent='☀️'}})}})();

// =====================================================
// SHORTCUTS + ENTER = NEXT + COMMAND PALETTE
// =====================================================
function showShortcutHelp(){const body='<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;font-size:13px"><div><h4>Navigation (Alt + key)</h4><div style="line-height:1.9"><div><span class="kbd">Alt+O</span> Dashboard</div><div><span class="kbd">Alt+I</span> Inventory</div><div><span class="kbd">Alt+K</span> Racks</div><div><span class="kbd">Alt+U</span> Purchases</div><div><span class="kbd">Alt+L</span> Sales/POS</div><div><span class="kbd">Alt+R</span> Repairing</div><div><span class="kbd">Alt+C</span> Customers</div><div><span class="kbd">Alt+S</span> Suppliers</div><div><span class="kbd">Alt+D</span> Udhar</div><div><span class="kbd">Alt+E</span> Expenses</div><div><span class="kbd">Alt+P</span> Reports</div><div><span class="kbd">Alt+T</span> Transactions</div><div><span class="kbd">Alt+,</span> Staff & Logs</div></div></div><div><h4>POS / Actions</h4><div style="line-height:1.9"><div><span class="kbd">F1</span> Help</div><div><span class="kbd">F2</span> Add to Cart</div><div><span class="kbd">F3</span> POS Search Focus</div><div><span class="kbd">F4</span> Save Sale</div><div><span class="kbd">F5</span> Refresh</div><div><span class="kbd">F6</span> Hold</div><div><span class="kbd">F7</span> Resume</div><div><span class="kbd">F8</span> New Purchase</div><div><span class="kbd">F9</span> New Expense</div><div><span class="kbd">F10</span> New Repair</div><div><span class="kbd">Ctrl+K</span> Command Palette</div><div><span class="kbd">Enter</span> Next Field / Save</div><div><span class="kbd">Esc</span> Close</div></div></div></div>';openModal('Keyboard Shortcuts',body,async()=>closeModal(),'Close')}
function openCommandPalette(){const cmds=[['+ New Sale','sales'],['+ New Purchase','purchases'],['+ New Expense','expenses'],['+ New Repair','repairing'],['+ New Customer','customers'],['Udhar / Credit','credit'],['Reports & P&L','reports'],['Transactions','transactions'],['Staff & Logs','settings']];const body='<div class="field"><label>Command likhein</label><input id="cmdInput" placeholder="sale, purchase, udhar, report..."></div><div id="cmdResults" style="display:grid;gap:6px">'+cmds.map(c=>'<button class="btn btn-ghost" data-cmd="'+c[1]+'" style="justify-content:flex-start">'+c[0]+'</button>').join('')+'</div>';openModal('Command Palette - Ctrl+K',body,async()=>closeModal(),'Close');setTimeout(()=>{const inp=$('cmdInput');inp?.focus();inp?.addEventListener('input',()=>{const q=bmNorm(inp.value);document.querySelectorAll('#cmdResults button').forEach(b=>{b.style.display=!q||bmNorm(b.textContent).includes(q)?'flex':'none'})});document.querySelectorAll('#cmdResults button').forEach(b=>b.addEventListener('click',()=>{closeModal();navTo(b.dataset.cmd)}))},80)}
document.addEventListener('keydown',e=>{const typing=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if(e.key==='Escape'){closeModal();$('notifPanel')?.classList.remove('open');return}if(e.ctrlKey&&e.key.toLowerCase()==='k'){e.preventDefault();openCommandPalette();return}if(e.altKey&&!e.ctrlKey&&!e.metaKey){const k=e.key.toLowerCase();if(MODULE_KEYS[k]){e.preventDefault();navTo(MODULE_KEYS[k]);return}}if(!typing){if(e.key==='F1'){e.preventDefault();showShortcutHelp()}if(e.key==='F2'){e.preventDefault();$('btnAddToCart')?.click()}if(e.key==='F3'){e.preventDefault();focusPOS()}if(e.key==='F4'){e.preventDefault();$('btnSaveSale')?.click()}if(e.key==='F5'){e.preventDefault();const a=document.querySelector('.module.active')?.id.replace('module-','');if(a)navTo(a);toast('Refreshed','info')}if(e.key==='F6'){e.preventDefault();$('btnHoldSale')?.click()}if(e.key==='F7'){e.preventDefault();$('btnResumeSale')?.click()}if(e.key==='F8'){e.preventDefault();$('btnNewPurchase')?.click()}if(e.key==='F9'){e.preventDefault();$('btnAddExpense')?.click()}if(e.key==='F10'){e.preventDefault();$('btnAddRepair')?.click()}}});
function focusableIn(root){return [...root.querySelectorAll('input:not([type=hidden]):not([disabled]):not([readonly]),select:not([disabled]),textarea:not([disabled]),button:not([disabled])')].filter(el=>el.offsetParent!==null||el===document.activeElement)}
function attachEnterNavigation(root){if(!root||root.dataset.enterBound)return;root.dataset.enterBound='1';root.addEventListener('keydown',e=>{if(e.key!=='Enter')return;const t=e.target;if(!['INPUT','SELECT','TEXTAREA'].includes(t.tagName))return;if(t.tagName==='TEXTAREA'&&!e.ctrlKey)return;if(['posDynamicSearch','posBarcodeInput','posProductSearch','cmdInput'].includes(t.id))return;e.preventDefault();const list=focusableIn(root);const idx=list.indexOf(t);if(idx>=0&&idx<list.length-1){list[idx+1].focus();try{list[idx+1].select()}catch(_){}}else{const cb=$('modalConfirm');if(root.contains($('modalBody'))&&cb&&!cb.disabled)cb.click();else if($('btnSaveSale')&&document.querySelector('#module-sales.active'))$('btnSaveSale').click();}})}
document.querySelector('.search-bar input')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();globalSearch(e.target.value)}});
async function globalSearch(q){q=(q||'').trim();if(!q)return;const l=q.toLowerCase();if(l.includes('udhar')||l.includes('credit'))navTo('credit');else if(l.includes('purchase'))navTo('purchases');else if(l.includes('expense')||l.includes('kharcha'))navTo('expenses');else if(l.includes('report')||l.includes('profit'))navTo('reports');else if(l.includes('repair'))navTo('repairing');else if(l.includes('customer'))navTo('customers');else if(l.includes('supplier'))navTo('suppliers');else{navTo('sales');setTimeout(()=>{const d=$('posDynamicSearch');if(d){d.value=q;d.dispatchEvent(new Event('input'));d.focus()}},200)}}
async function loadNotifs(){try{const{data}=await supabase.from('sales').select('customer_name,balance,invoice_no').gt('balance',0).order('created_at',{ascending:false}).limit(20);const due=data||[];const badge=$('notifBadge'),panel=$('notifPanel');if(badge){badge.textContent=due.length;badge.style.display=due.length?'flex':'none'}if(panel)panel.innerHTML='<h3 style="font-size:14px;margin:0 0 10px">Pending Udhar ('+due.length+')</h3>'+(due.length?due.map(d=>'<div class="notif-item"><b>'+esc(d.customer_name||'Walk-in')+'</b> - '+fmt(d.balance)+' <small>'+esc(d.invoice_no||'')+'</small></div>').join(''):'<div class="empty">Koi pending udhar nahi.</div>')}catch(e){}}
setInterval(loadNotifs,60000);
function focusPOS(){const el=$('posDynamicSearch')||$('posProductSearch');if(el){el.focus();try{el.select()}catch(_){}}}

