// =====================================================
function ensurePLCard(){if($('plChartCard'))return;const ov=$('module-overview');if(!ov)return;const card=document.createElement('div');card.className='card';card.id='plChartCard';card.innerHTML='<div class="toolbar"><h3>Daily Profit / Loss - Last 30 Days</h3><div class="toolbar-actions"><select id="plRange" class="form-input"><option value="7">Last 7 Days</option><option value="14">Last 14 Days</option><option value="30" selected>Last 30 Days</option></select><button class="btn btn-ghost" onclick="window.exportDailyPL && window.exportDailyPL()">Export CSV</button><button class="btn btn-ghost" onclick="loadDailyPL()">Refresh</button></div></div><div class="stats-grid" style="margin-bottom:14px"><div class="stat"><div class="stat-icon green">P</div><div><strong id="plTodayProfit">PKR 0</strong><small>Today Net Profit</small></div></div><div class="stat"><div class="stat-icon purple">M</div><div><strong id="plMonthProfit">PKR 0</strong><small>Month Net Profit</small></div></div><div class="stat"><div class="stat-icon red">L</div><div><strong id="plMonthLoss">PKR 0</strong><small>Month Loss Days Total</small></div></div><div class="stat"><div class="stat-icon blue">B</div><div><strong id="plBestDay">-</strong><small>Best Profit Day</small></div></div></div><canvas id="plChartCanvas" width="1000" height="280" style="width:100%;height:280px;background:var(--bg-soft);border-radius:12px"></canvas><div id="plDailyTable" style="margin-top:14px"></div><p style="font-size:12px;color:var(--muted,#64748B);margin-top:8px">Formula: <b>Net = Revenue - COGS (purchase cost) - Expenses</b> | COGS = sale item qty x product purchase price (missing ho to sale price ka 85% estimate).</p>';const stats=ov.querySelector('.stats-grid');if(stats)stats.after(card);else ov.prepend(card);$('plRange')?.addEventListener('change',()=>loadDailyPL())}
async function computeDailyPL(days){days=days||30;const from=new Date();from.setDate(from.getDate()-(days-1));from.setHours(0,0,0,0);const fromISO=from.toISOString();const [salesRes,itemsRes,expRes]=await Promise.all([supabase.from('sales').select('id,total,created_at').gte('created_at',fromISO).order('created_at'),supabase.from('sale_items').select('sale_id,product_id,quantity,unit_price,line_total').gte('created_at',fromISO).limit(5000),supabase.from('expenses').select('amount,created_at').gte('created_at',fromISO)]);const sales=salesRes.data||[],items=itemsRes.data||[],exps=expRes.data||[];const prodIds=[...new Set(items.map(i=>i.product_id).filter(Boolean))];let costMap={};if(prodIds.length){const{data:prods}=await supabase.from('products').select('id,purchase_price,sale_price').in('id',prodIds);(prods||[]).forEach(pp=>costMap[pp.id]=Number(pp.purchase_price||0))}const byDay={};for(let i=0;i<days;i++){const d=new Date(from);d.setDate(from.getDate()+i);const k=d.toISOString().slice(0,10);byDay[k]={date:k,revenue:0,cogs:0,exp:0,orders:0}}sales.forEach(ss=>{const k=(ss.created_at||'').slice(0,10);if(byDay[k]){byDay[k].revenue+=Number(ss.total||0);byDay[k].orders++}});const saleById={};sales.forEach(ss=>saleById[ss.id]=ss);items.forEach(it=>{const sale=saleById[it.sale_id];if(!sale)return;const k=(sale.created_at||'').slice(0,10);if(!byDay[k])return;const unit=costMap[it.product_id]||Number(it.unit_price||0)*0.85;byDay[k].cogs+=unit*Number(it.quantity||1)});exps.forEach(e=>{const k=(e.created_at||'').slice(0,10);if(byDay[k])byDay[k].exp+=Number(e.amount||0)});return Object.values(byDay).map(d=>({...d,gross:d.revenue-d.cogs,net:d.revenue-d.cogs-d.exp}))}
function drawPLChart(rows){const cv=$('plChartCanvas');if(!cv)return;const ctx=cv.getContext('2d');const W=cv.width,H=cv.height;ctx.clearRect(0,0,W,H);const max=Math.max(1,...rows.map(r=>Math.abs(r.net)),...rows.map(r=>r.revenue));const padL=64,padB=30,padT=18,plotW=W-padL-16,plotH=H-padT-padB,zeroY=padT+plotH/2;ctx.strokeStyle='#CBD5E1';ctx.beginPath();ctx.moveTo(padL,zeroY);ctx.lineTo(W-16,zeroY);ctx.stroke();ctx.fillStyle='#64748B';ctx.font='11px Arial';ctx.fillText(fmt(max),4,padT+4);ctx.fillText('0',4,zeroY+4);ctx.fillText('-'+fmt(max),4,H-8);const bw=plotW/rows.length;rows.forEach((r,i)=>{const x=padL+i*bw+bw*0.15,w=bw*0.7;const h=Math.abs(r.net)/max*(plotH/2);const y=r.net>=0?zeroY-h:zeroY;ctx.fillStyle=r.net>=0?'#10B981':'#EF4444';ctx.fillRect(x,y,w,Math.max(h,2));ctx.fillStyle='#334155';ctx.font='10px Arial';ctx.fillText(new Date(r.date).toLocaleDateString('en-PK',{day:'numeric',month:'short'}),x-4,H-8)});ctx.fillStyle='#0F172A';ctx.font='bold 12px Arial';ctx.fillText('Green = Profit  |  Red = Loss  |  Bar = Net per Day',padL,13)}
async function loadDailyPL(){ensurePLCard();const days=Number($('plRange')?.value||30);try{const rows=await computeDailyPL(days);drawPLChart(rows);const today=rows.find(r=>r.date===bmTodayISO());const thisMonth=rows.filter(r=>r.date.slice(0,7)===bmTodayISO().slice(0,7));const mNet=thisMonth.reduce((a,r)=>a+r.net,0),mLoss=thisMonth.filter(r=>r.net<0).reduce((a,r)=>a+Math.abs(r.net),0);const best=[...rows].sort((a,b)=>b.net-a.net)[0];if($('plTodayProfit'))$('plTodayProfit').textContent=fmt(today?.net||0);if($('plMonthProfit'))$('plMonthProfit').textContent=fmt(mNet);if($('plMonthLoss'))$('plMonthLoss').textContent=fmt(mLoss);if($('plBestDay'))$('plBestDay').textContent=best?fmt(best.net)+' | '+new Date(best.date).toLocaleDateString('en-PK',{day:'numeric',month:'short'}):'-';window._DAILY_PL=rows;if($('plDailyTable'))$('plDailyTable').innerHTML='<table class="data"><thead><tr><th>Date</th><th class="num">Revenue</th><th class="num">COGS</th><th class="num">Gross</th><th class="num">Expenses</th><th class="num">Net P/L</th><th class="num">Orders</th></tr></thead><tbody>'+[...rows].reverse().map(r=>'<tr><td><b>'+new Date(r.date).toLocaleDateString('en-PK',{weekday:'short',day:'numeric',month:'short'})+'</b></td><td class="num">'+fmt(r.revenue)+'</td><td class="num">'+fmt(r.cogs)+'</td><td class="num">'+fmt(r.gross)+'</td><td class="num">'+fmt(r.exp)+'</td><td class="num" style="color:'+(r.net>=0?'#059669':'#DC2626')+';font-weight:800">'+(r.net>=0?'+':'')+fmt(r.net)+'</td><td class="num">'+r.orders+'</td></tr>').join('')+'</tbody></table>'}catch(e){if($('plDailyTable'))$('plDailyTable').innerHTML='<div class="empty">P&L load nahi hua: '+esc(e.message)+'</div>'}}
window.exportDailyPL=()=>{const rows=window._DAILY_PL||[];if(!rows.length)return toast('Pehle P&L load karo','error');let csv='Date,Revenue,COGS,Gross,Expenses,Net,Orders\n';rows.forEach(r=>csv+=r.date+','+r.revenue+','+r.cogs+','+r.gross+','+r.exp+','+r.net+','+r.orders+'\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='Daily_PL_'+Date.now()+'.csv';a.click();toast('Daily P&L exported!','success')};
async function loadOverview(){ensurePLCard();loadDailyPL();try{const [prods,sales,purch,cust,exps]=await Promise.all([supabase.from('products').select('quantity').limit(5000),supabase.from('sales').select('total,created_at').order('created_at',{ascending:false}).limit(5000),supabase.from('purchases').select('total').limit(5000),supabase.from('customers').select('id').limit(5000),supabase.from('expenses').select('amount')]);const today=bmTodayISO(),month=today.slice(0,7);const sum=a=>a.reduce((a2,r)=>a2+Number(r.total||r.amount||0),0);const tSales=(sales.data||[]).filter(s=>s.created_at?.slice(0,10)===today),mSales=(sales.data||[]).filter(s=>s.created_at?.slice(0,7)===month);const stock=(prods.data||[]).reduce((a,p)=>a+Number(p.quantity||0),0);const set=(id,v)=>{if($(id))$(id).textContent=v};set('stProducts',String((prods.data||[]).length));set('stStock',String(stock));set('stTodaySales',fmt(sum(tSales)));set('stMonthSales',fmt(sum(mSales)));set('stPurchases',fmt(sum(purch.data||[])));set('stCustomers',String((cust.data||[]).length));set('stExpenses',fmt(sum(exps.data||[])));const{data:due}=await supabase.from('sales').select('balance').gt('balance',0);set('stOutstanding',fmt((due||[]).reduce((a,r)=>a+Number(r.balance||0),0)));const{data:recent}=await supabase.from('sales').select('*').order('created_at',{ascending:false}).limit(8);if($('recentSales'))$('recentSales').innerHTML=(recent||[]).length?'<table class="data"><thead><tr><th>Invoice</th><th>Customer</th><th class="num">Total</th><th class="num">Paid</th><th class="num">Balance</th><th>Date</th></tr></thead><tbody>'+recent.map(s=>'<tr><td><b>'+esc(s.invoice_no)+'</b></td><td>'+esc(s.customer_name||'Walk-in')+'</td><td class="num">'+fmt(s.total)+'</td><td class="num">'+fmt(s.paid)+'</td><td class="num">'+fmt(s.balance)+'</td><td><small>'+new Date(s.created_at).toLocaleDateString('en-PK')+'</small></td></tr>').join('')+'</tbody></table>':'<div class="empty">No sales yet.</div>'}catch(e){console.warn(e.message)}loadNotifs()}

