// INVENTORY + RACKS
// =====================================================
async function loadInventory(){try{const rack=$('inventoryRackFilter')?.value||'';let q=supabase.from('products').select('*').order('quantity');if(rack)q=q.eq('rack_id',rack);const{data}=await q;const list=data||[];const low=list.filter(pp=>Number(pp.quantity||0)<=Number(pp.min_stock||5));if($('lowStockTable'))$('lowStockTable').innerHTML=low.length?'<table class="data"><thead><tr><th>Product</th><th>Brand</th><th>Category</th><th class="num">Stock</th><th class="num">Min</th><th class="num">Buy</th><th class="num">Sale</th><th>Action</th></tr></thead><tbody>'+low.map(pp=>'<tr><td><b>'+esc(pp.name)+'</b></td><td>'+esc(pp.brand||'-')+'</td><td>'+esc(pp.category||'-')+'</td><td class="num" style="color:#DC2626;font-weight:800">'+pp.quantity+'</td><td class="num">'+(pp.min_stock||5)+'</td><td class="num">'+fmt(pp.purchase_price)+'</td><td class="num">'+fmt(pp.sale_price)+'</td><td><button class="btn btn-sm btn-primary" onclick="window.quickRestock(\''+pp.id+'\')">+ Restock</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">Koi low stock nahi.</div>';const{data:mov}=await supabase.from('sales').select('invoice_no,created_at,customer_name').order('created_at',{ascending:false}).limit(10);if($('movementsTable'))$('movementsTable').innerHTML=(mov||[]).length?'<table class="data"><thead><tr><th>Type</th><th>Ref</th><th>Party</th><th>Date</th></tr></thead><tbody>'+mov.map(m=>'<tr><td><span class="pill red">OUT</span></td><td>'+esc(m.invoice_no)+'</td><td>'+esc(m.customer_name||'Walk-in')+'</td><td>'+new Date(m.created_at).toLocaleDateString('en-PK')+'</td></tr>').join('')+'</tbody></table>':'<div class="empty">No movements.</div>'}catch(e){if($('lowStockTable'))$('lowStockTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
window.quickRestock=async(id)=>{const pp=ALL_PRODUCTS.find(x=>x.id===id);if(!pp)return;const qty=Number(prompt('Kitni quantity add karni hai?','10')||0);if(qty<=0)return;await supabase.from('products').update({quantity:Number(pp.quantity||0)+qty}).eq('id',id);toast('Stock updated!','success');loadInventory();loadProducts()};
async function loadRacks(){try{const q=$('rackSearchInput')?.value?.trim().toLowerCase()||'';const{data}=await supabase.from('racks').select('*').order('name');let list=data||[];if(q)list=list.filter(r=>(r.name||'').toLowerCase().includes(q));ALL_RACKS=list;if($('racksTable'))$('racksTable').innerHTML=list.length?'<table class="data"><thead><tr><th>Rack</th><th>Description</th><th>Actions</th></tr></thead><tbody>'+list.map(r=>'<tr><td><b>'+esc(r.name)+'</b></td><td>'+esc(r.description||'-')+'</td><td><button class="btn btn-sm" onclick="window.viewRackStock(\''+r.id+'\')">Stock</button> <button class="btn btn-sm" onclick="window.editRack(\''+r.id+'\')">Edit</button> <button class="btn btn-sm btn-danger" onclick="window.deleteRack(\''+r.id+'\')">Delete</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">No racks.</div>';const{data:prods}=await supabase.from('products').select('name,quantity,rack_id');const byRack={};(prods||[]).forEach(pp=>{byRack[pp.rack_id||'none']=(byRack[pp.rack_id||'none']||0)+Number(pp.quantity||0)});if($('rackStockTable'))$('rackStockTable').innerHTML=list.length?'<table class="data"><thead><tr><th>Rack</th><th class="num">Total Qty</th></tr></thead><tbody>'+list.map(r=>'<tr><td><b>'+esc(r.name)+'</b></td><td class="num">'+(byRack[r.id]||0)+'</td></tr>').join('')+'</tbody></table>':'<div class="empty">No racks.</div>'}catch(e){if($('racksTable'))$('racksTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
$('rackSearchInput')?.addEventListener('input',loadRacks);
$('btnAddRack')?.addEventListener('click',()=>openRackModal());
function openRackModal(r){r=r||null;const body='<div class="form-grid"><div class="field"><label>Rack Name *</label><input id="rackName" value="'+esc(r?.name||'')+'"></div><div class="field full"><label>Description</label><input id="rackDesc" value="'+esc(r?.description||'')+'"></div></div>';openModal(r?'Edit Rack':'Add Rack',body,async()=>{const name=$('rackName').value.trim();if(!name)throw new Error('Rack name required');if(r)await supabase.from('racks').update({name,description:$('rackDesc').value.trim()||null}).eq('id',r.id);else await supabase.from('racks').insert({name,description:$('rackDesc').value.trim()||null});closeModal();toast('Saved','success');loadRacks()},'Save')}
window.editRack=async id=>{const{data}=await supabase.from('racks').select('*').eq('id',id).single();if(data)openRackModal(data)};
window.deleteRack=async id=>{if(!checkPermission('delete'))return;if(!confirm('Delete rack?'))return;await supabase.from('racks').delete().eq('id',id);toast('Deleted');loadRacks()};
window.viewRackStock=async id=>{const{data}=await supabase.from('products').select('*').eq('rack_id',id);const r=ALL_RACKS.find(x=>x.id===id);openModal('Rack Stock - '+(r?.name||''),'<table class="data"><thead><tr><th>Product</th><th class="num">Qty</th><th class="num">Price</th></tr></thead><tbody>'+((data||[]).map(pp=>'<tr><td>'+esc(pp.name)+'</td><td class="num">'+pp.quantity+'</td><td class="num">'+fmt(pp.sale_price)+'</td></tr>').join('')||'<tr><td colspan="3">Empty</td></tr>')+'</tbody></table>',async()=>closeModal(),'Close')};
// =====================================================
// PRODUCTS + PURCHASES (MERGE ENGINE)
// =====================================================
let PRODUCT_FILTER={search:'',cat:'',brand:''};
async function loadProducts(){try{const{data}=await supabase.from('products').select('*').order('name');ALL_PRODUCTS=data||[];const cats=[...new Set(ALL_PRODUCTS.map(pp=>pp.category).filter(Boolean))];const brands=[...new Set(ALL_PRODUCTS.map(pp=>pp.brand).filter(Boolean))];const cf=$('productFilterCat');if(cf)cf.innerHTML='<option value="">All Categories</option>'+cats.map(c=>'<option value="'+esc(c)+'" '+(PRODUCT_FILTER.cat===c?'selected':'')+'>'+esc(c)+'</option>').join('');const bf=$('productFilterBrand');if(bf)bf.innerHTML='<option value="">All Brands</option>'+brands.map(b=>'<option value="'+esc(b)+'" '+(PRODUCT_FILTER.brand===b?'selected':'')+'>'+esc(b)+'</option>').join('');let f=[...ALL_PRODUCTS];if(PRODUCT_FILTER.search){const q=PRODUCT_FILTER.search.toLowerCase();f=f.filter(pp=>(pp.name||'').toLowerCase().includes(q)||(pp.brand||'').toLowerCase().includes(q)||(pp.category||'').toLowerCase().includes(q)||(pp.imei_1||'').includes(q)||(pp.imei_2||'').includes(q)||(pp.barcode||'').includes(q))}if(PRODUCT_FILTER.cat)f=f.filter(pp=>pp.category===PRODUCT_FILTER.cat);if(PRODUCT_FILTER.brand)f=f.filter(pp=>pp.brand===PRODUCT_FILTER.brand);const t=$('productsTable');if(!t)return;if(!f.length){t.innerHTML='<div class="empty">'+(ALL_PRODUCTS.length?'No products match.':'No products. Add from Purchase section.')+'</div>';return}t.innerHTML='<table class="data"><thead><tr><th><input type="checkbox" onchange="toggleAllProd(this)"></th><th>Product</th><th>Brand</th><th>Category</th><th class="num">Qty</th><th class="num">Buy</th><th class="num">Sale</th><th class="num">Margin</th><th>IMEI 1</th><th>Actions</th></tr></thead><tbody>'+f.map(pp=>{const margin=Number(pp.sale_price||0)-Number(pp.purchase_price||0);return '<tr><td><input type="checkbox" class="prod-check" value="'+pp.id+'" onchange="updateProdBulk()"></td><td><b>'+esc(pp.name)+'</b></td><td>'+esc(pp.brand||'-')+'</td><td><span class="pill blue">'+esc(pp.category||'General')+'</span></td><td class="num" style="color:'+(Number(pp.quantity||0)<=Number(pp.min_stock||5)?'#DC2626':'inherit')+';font-weight:700">'+pp.quantity+'</td><td class="num">'+fmt(pp.purchase_price)+'</td><td class="num">'+fmt(pp.sale_price)+'</td><td class="num" style="color:#059669">'+fmt(margin)+'</td><td><small>'+esc(pp.imei_1||'-')+'</small></td><td><button class="btn btn-sm" onclick="window.editProduct(\''+pp.id+'\')">Edit</button> <button class="btn btn-sm btn-danger" onclick="window.deleteProduct(\''+pp.id+'\')">Del</button></td></tr>'}).join('')+'</tbody></table>'}catch(e){if($('productsTable'))$('productsTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
$('productSearch')?.addEventListener('input',e=>{PRODUCT_FILTER.search=e.target.value;loadProducts()});
$('productFilterCat')?.addEventListener('change',e=>{PRODUCT_FILTER.cat=e.target.value;loadProducts()});
$('productFilterBrand')?.addEventListener('change',e=>{PRODUCT_FILTER.brand=e.target.value;loadProducts()});
window.toggleAllProd=cb=>{document.querySelectorAll('.prod-check').forEach(c=>c.checked=cb.checked);updateProdBulk()};
function updateProdBulk(){const n=document.querySelectorAll('.prod-check:checked').length;const bar=$('productBulkBar');if(bar)bar.style.display=n?'flex':'none';if($('productSelCount'))$('productSelCount').textContent=n}
window.bulkDeleteProducts=async()=>{if(!checkPermission('delete'))return;const ids=[...document.querySelectorAll('.prod-check:checked')].map(c=>c.value);if(!ids.length||!confirm('Delete '+ids.length+' products?'))return;await supabase.from('products').delete().in('id',ids);toast('Deleted');loadProducts()};
window.editProduct=async id=>{if(!checkPermission('edit'))return;const pp=ALL_PRODUCTS.find(x=>x.id===id);if(!pp)return;const body='<div class="form-grid"><div class="field"><label>Name *</label><input id="peName" value="'+esc(pp.name)+'"></div><div class="field"><label>Category</label><input id="peCat" list="catList" value="'+esc(pp.category||'')+'"><datalist id="catList">'+CATEGORIES.map(c=>'<option value="'+c+'">').join('')+'</datalist></div><div class="field"><label>Brand</label><input id="peBrand" list="brandList" value="'+esc(pp.brand||'')+'"><datalist id="brandList">'+BRANDS.map(b=>'<option value="'+b+'">').join('')+'</datalist></div><div class="field"><label>Qty</label><input id="peQty" type="number" value="'+pp.quantity+'"></div><div class="field"><label>Buy Price</label><input id="pePPrice" type="number" value="'+pp.purchase_price+'"></div><div class="field"><label>Sale Price</label><input id="peSPrice" type="number" value="'+pp.sale_price+'"></div><div class="field"><label>Min Stock</label><input id="peMin" type="number" value="'+(pp.min_stock||5)+'"></div><div class="field"><label>IMEI 1</label><input id="peImei1" value="'+esc(pp.imei_1||'')+'"></div><div class="field"><label>IMEI 2</label><input id="peImei2" value="'+esc(pp.imei_2||'')+'"></div></div>';openModal('Edit Product',body,async()=>{const payload={name:$('peName').value.trim(),category:$('peCat').value.trim()||'General',brand:$('peBrand').value.trim()||null,quantity:Number($('peQty').value)||0,purchase_price:Number($('pePPrice').value)||0,sale_price:Number($('peSPrice').value)||0,min_stock:Number($('peMin').value)||5,imei_1:$('peImei1').value.trim()||null,imei_2:$('peImei2').value.trim()||null};if(!payload.name)throw new Error('Name required');await supabase.from('products').update(payload).eq('id',id);await logActivity('EDIT','products',payload.name);closeModal();toast('Saved','success');loadProducts()},'Save')};
window.deleteProduct=async id=>{if(!checkPermission('delete'))return;if(!confirm('Delete product?'))return;await supabase.from('products').delete().eq('id',id);toast('Deleted');loadProducts()};
window.quickExportProducts=()=>{let csv='Name,Brand,Category,Qty,Buy,Sale,IMEI1,IMEI2\n';ALL_PRODUCTS.forEach(pp=>csv+='"'+pp.name+'","'+(pp.brand||'')+'","'+(pp.category||'')+'",'+pp.quantity+','+pp.purchase_price+','+pp.sale_price+',"'+(pp.imei_1||'')+'","'+(pp.imei_2||'')+'"\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='Products_'+Date.now()+'.csv';a.click();toast('Exported!','success')};

// ---------- PURCHASES ----------
async function loadPurchasesModule(){loadProducts();const box=$('purchasesHistoryBox');if(box&&!box.hidden)loadPurchasesHistory()}
$('btnNewPurchase')?.addEventListener('click',()=>openPurchaseModal());
$('btnPurchasesHistory')?.addEventListener('click',()=>{const box=$('purchasesHistoryBox');box.hidden=!box.hidden;if(!box.hidden)loadPurchasesHistory()});
$('btnRefreshPurchases')?.addEventListener('click',()=>{loadProducts();loadPurchasesHistory()});
async function loadPurchasesHistory(){try{const{data}=await supabase.from('purchases').select('*,suppliers(name)').order('created_at',{ascending:false}).limit(100);const t=$('purchasesTable');if(!t)return;t.innerHTML=(data||[]).length?'<table class="data"><thead><tr><th>Invoice</th><th>Supplier</th><th class="num">Total</th><th class="num">Paid</th><th class="num">Due</th><th>Date</th><th>Actions</th></tr></thead><tbody>'+data.map(pu=>'<tr><td><b>'+esc(pu.invoice_no||'')+'</b></td><td>'+esc(pu.suppliers?.name||'-')+'</td><td class="num">'+fmt(pu.total)+'</td><td class="num">'+fmt(pu.paid)+'</td><td class="num" style="color:#DC2626">'+fmt(Number(pu.total||0)-Number(pu.paid||0))+'</td><td><small>'+new Date(pu.created_at).toLocaleDateString('en-PK')+'</small></td><td><button class="btn btn-sm" onclick="window.printPurchase(\''+pu.id+'\')">Print</button> <button class="btn btn-sm" onclick="window.editPurchase(\''+pu.id+'\')">Edit</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">No purchases yet.</div>'}catch(e){if($('purchasesTable'))$('purchasesTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
window.editPurchase=async id=>{const{data}=await supabase.from('purchases').select('*').eq('id',id).single();if(data)openPurchaseModal(data)};
window.printPurchase=async id=>{const{data}=await supabase.from('purchases').select('*').eq('id',id).single();if(!data)return;const{data:items}=await supabase.from('purchase_items').select('*').eq('purchase_id',id);printA4Premium({invoice:data.invoice_no,total:data.total,paid:data.paid,balance:Number(data.total||0)-Number(data.paid||0),items:(items||[]).map(i=>({name:i.product_name,quantity:i.quantity,unit_price:i.purchase_price,line_total:i.total})),customer:'Supplier Purchase'},'sale')};
function addPurchaseItemRow(prefill){prefill=prefill||{};const host=$('purchaseItemsHost');if(!host)return;const row=document.createElement('div');row.className='product-item-row';row.innerHTML='<input class="pi-name" list="prodMasterList" placeholder="Product name likhein..." value="'+esc(prefill.product_name||'')+'"><input class="pi-cat" list="catList" placeholder="Category" value="'+esc(prefill.category||'')+'"><datalist id="catList">'+CATEGORIES.map(c=>'<option value="'+c+'">').join('')+'</datalist><input class="pi-brand" list="brandList" placeholder="Brand" value="'+esc(prefill.brand||'')+'"><datalist id="brandList">'+BRANDS.map(b=>'<option value="'+b+'">').join('')+'</datalist><input class="pi-qty" type="number" value="'+(prefill.quantity||1)+'" min="1"><input class="pi-buy" type="number" value="'+(prefill.purchase_price||0)+'"><input class="pi-sale" type="number" value="'+(prefill.sale_price||0)+'"><input class="pi-imei1" placeholder="IMEI 1" value="'+esc(prefill.imei_1||'')+'"><input class="pi-imei2" placeholder="IMEI 2" value="'+esc(prefill.imei_2||'')+'"><select class="pi-rack"><option value="">Rack?</option>'+ALL_RACKS.map(r=>'<option value="'+r.id+'" '+(prefill.rack_id===r.id?'selected':'')+'>'+esc(r.name)+'</option>').join('')+'</select><button type="button" class="item-del-btn" onclick="this.closest(\'.product-item-row\').remove();window.recalcPurchaseTotal&&window.recalcPurchaseTotal()">x</button>';host.appendChild(row);const nameIn=row.querySelector('.pi-name');nameIn.addEventListener('change',()=>{const opt=document.querySelector('#prodMasterList option[value="'+CSS.escape(nameIn.value)+'"]');const prod=ALL_PRODUCTS.find(pp=>pp.name===nameIn.value);if(prod||opt){const src=prod||{category:opt?.dataset.cat,brand:opt?.dataset.brand,purchase_price:opt?.dataset.buy,sale_price:opt?.dataset.sale,imei_1:opt?.dataset.imei1,imei_2:opt?.dataset.imei2};row.querySelector('.pi-cat').value=src.category||'';row.querySelector('.pi-brand').value=src.brand||'';row.querySelector('.pi-buy').value=src.purchase_price||0;row.querySelector('.pi-sale').value=src.sale_price||0;row.querySelector('.pi-imei1').value=src.imei_1||'';row.querySelector('.pi-imei2').value=src.imei_2||'';}});row.querySelectorAll('input').forEach(inp=>inp.addEventListener('input',()=>window.recalcPurchaseTotal&&window.recalcPurchaseTotal()));attachEnterNavigation(row);window.recalcPurchaseTotal&&window.recalcPurchaseTotal();nameIn.focus()}
window.addPurchaseItemRow=()=>addPurchaseItemRow();
window.recalcPurchaseTotal=()=>{let total=0;document.querySelectorAll('#purchaseItemsHost .product-item-row').forEach(r=>{total+=(Number(r.querySelector('.pi-qty')?.value)||0)*(Number(r.querySelector('.pi-buy')?.value)||0)});if($('puTotal'))$('puTotal').value=total};
window.addCustomCategory=()=>{const c=prompt('Nayi Category ka naam:');if(c&&!CATEGORIES.includes(c)){CATEGORIES.push(c);toast('Category added: '+c,'success')}};
window.addCustomBrand=()=>{const b=prompt('Naya Brand ka naam:');if(b&&!BRANDS.includes(b)){BRANDS.push(b);toast('Brand added: '+b,'success')}};
async function openPurchaseModal(pu){pu=pu||null;const{data:sups}=await supabase.from('suppliers').select('id,name').order('name');const{data:racks}=await supabase.from('racks').select('id,name').order('name');ALL_RACKS=racks||[];const prodOptions=ALL_PRODUCTS.map(prod=>'<option value="'+esc(prod.name)+'" data-id="'+prod.id+'" data-cat="'+esc(prod.category)+'" data-brand="'+esc(prod.brand||'')+'" data-buy="'+prod.purchase_price+'" data-sale="'+prod.sale_price+'" data-imei1="'+esc(prod.imei_1||'')+'" data-imei2="'+esc(prod.imei_2||'')+'">'+esc(prod.name)+'</option>').join('');const body='<div style="display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:16px;margin-bottom:20px"><div class="field"><label>Supplier</label><select id="puSup"><option value="">- None -</option>'+((sups||[]).map(s=>'<option value="'+s.id+'" '+(pu?.supplier_id===s.id?'selected':'')+'>'+esc(s.name)+'</option>').join(''))+'</select></div><div class="field"><label>Invoice No</label><input id="puInv" value="'+esc(pu?.invoice_no||'')+'" placeholder="Auto if blank"></div><div class="field"><label>Total (Auto)</label><input id="puTotal" type="number" value="'+(pu?.total||0)+'" readonly></div><div class="field"><label>Paid</label><input id="puPaid" type="number" value="'+(pu?.paid||0)+'"></div><div class="field full"><label>Notes</label><input id="puNotes" value="'+esc(pu?.notes||'')+'"></div></div><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><div><h4 style="margin:0">Products / Items</h4><p style="font-size:11px;color:var(--muted)">Type name to auto-fill. <b>Alt+A</b> add row, <b>Ctrl+Enter</b> save.</p></div><div style="display:flex;gap:8px"><button type="button" class="btn btn-ghost btn-sm" onclick="addCustomCategory()">+ Category</button><button type="button" class="btn btn-ghost btn-sm" onclick="addCustomBrand()">+ Brand</button><button type="button" class="btn btn-primary btn-sm" onclick="addPurchaseItemRow()">+ Add Item</button></div></div><div class="items-header-labels"><span>Product Name</span><span>Category</span><span>Brand</span><span>Qty</span><span>Buy</span><span>Sale</span><span>IMEI 1</span><span>IMEI 2</span><span>Rack</span><span></span></div><div id="purchaseItemsHost"></div><datalist id="prodMasterList">'+prodOptions+'</datalist>';openModal(pu?'Edit Purchase':'New Purchase Invoice',body,async()=>{const total=Number($('puTotal').value)||0;const invoiceNo=$('puInv').value.trim()||('PUR-'+Date.now().toString().slice(-6));const payload={supplier_id:$('puSup').value||null,invoice_no:invoiceNo,total,paid:Number($('puPaid').value)||0,notes:$('puNotes').value.trim()||null};let purchaseId=pu?.id;if(pu){const{error}=await supabase.from('purchases').update(payload).eq('id',pu.id);if(error)throw new Error(error.message);await supabase.from('purchase_items').delete().eq('purchase_id',pu.id)}else{const{data:created,error}=await supabase.from('purchases').insert(payload).select().single();if(error)throw new Error(error.message);purchaseId=created.id}const rows=[...document.querySelectorAll('#purchaseItemsHost .product-item-row')];const merged=new Map();rows.forEach(r=>{const name=r.querySelector('.pi-name')?.value.trim();if(!name)return;const key=bmNorm(r.querySelector('.pi-brand')?.value)+'|'+bmNorm(name)+'|'+bmNorm(r.querySelector('.pi-cat')?.value);const it={product_name:name,category:r.querySelector('.pi-cat')?.value.trim()||'General',brand:r.querySelector('.pi-brand')?.value.trim()||null,quantity:Number(r.querySelector('.pi-qty')?.value)||0,purchase_price:Number(r.querySelector('.pi-buy')?.value)||0,sale_price:Number(r.querySelector('.pi-sale')?.value)||0,imei_1:r.querySelector('.pi-imei1')?.value.trim()||null,imei_2:r.querySelector('.pi-imei2')?.value.trim()||null,rack_id:r.querySelector('.pi-rack')?.value||null};it.total=it.quantity*it.purchase_price;if(merged.has(key)){const old=merged.get(key);const tq=old.quantity+it.quantity;old.purchase_price=((old.purchase_price*old.quantity)+(it.purchase_price*it.quantity))/tq;old.quantity=tq;old.total=tq*old.purchase_price;old.sale_price=it.sale_price||old.sale_price}else merged.set(key,it)});const items=[...merged.values()];if(items.length){const{error}=await supabase.from('purchase_items').insert(items.map(i=>({...i,purchase_id:purchaseId})));if(error)throw new Error(error.message);for(const it of items){const{data:ex}=await supabase.from('products').select('*').eq('name',it.product_name).eq('brand',it.brand||'').eq('category',it.category).maybeSingle();if(ex){const nq=Number(ex.quantity||0)+it.quantity;const ncost=((Number(ex.purchase_price||0)*Number(ex.quantity||0))+(it.purchase_price*it.quantity))/Math.max(nq,1);await supabase.from('products').update({quantity:nq,purchase_price:ncost,sale_price:it.sale_price||ex.sale_price,rack_id:it.rack_id||ex.rack_id,imei_1:it.imei_1||ex.imei_1,imei_2:it.imei_2||ex.imei_2}).eq('id',ex.id)}else{await supabase.from('products').insert({name:it.product_name,category:it.category,brand:it.brand,quantity:it.quantity,purchase_price:it.purchase_price,sale_price:it.sale_price,imei_1:it.imei_1,imei_2:it.imei_2,rack_id:it.rack_id,min_stock:5})}}}await logActivity(pu?'EDIT':'CREATE','purchases',invoiceNo+' | '+fmt(total));closeModal();toast('Purchase saved!','success');loadPurchasesModule();loadOverview()},'Save Purchase');setTimeout(async()=>{if(pu){const{data:items}=await supabase.from('purchase_items').select('*').eq('purchase_id',pu.id);(items||[]).forEach(it=>addPurchaseItemRow(it))}else addPurchaseItemRow();document.addEventListener('keydown',function h(e){if(e.altKey&&e.key.toLowerCase()==='a'&&$('modalBackdrop')?.classList.contains('open')){e.preventDefault();addPurchaseItemRow()}}, {once:false})},120)}

// =====================================================
// POS - DYNAMIC SEARCH + AUTO FOCUS + CART
// =====================================================
let CART=[],HELD_CARTS=[];
function ensurePOSSearch(){let inp=$('posDynamicSearch');if(inp)return inp;const card=$('posProductSearch')?.closest('.card')||$('module-sales .card');if(!card)return null;const wrap=document.createElement('div');wrap.className='field';wrap.style.marginTop='14px';wrap.innerHTML='<label>Dynamic Search - Sab Kuch Search Karo (F3)</label><input id="posDynamicSearch" placeholder="Product / Brand / IMEI / Barcode / Customer / Invoice..."><div id="posDynamicResults" style="position:relative;z-index:20"></div>';const ref=$('posProductSearch')?.closest('.field');if(ref)ref.before(wrap);else card.prepend(wrap);return $('posDynamicSearch')}
function renderPOSResults(list){const box=$('posDynamicResults');if(!box)return;if(!list.length){box.innerHTML='';return}box.innerHTML='<div style="position:absolute;top:4px;left:0;right:0;background:var(--bg-card);border:1px solid var(--border);border-radius:10px;box-shadow:var(--shadow-lg);max-height:320px;overflow:auto">'+list.map((r,i)=>'<div class="pos-res" data-idx="'+i+'" style="padding:10px 12px;cursor:pointer;border-bottom:1px solid var(--border-light);display:flex;justify-content:space-between;gap:8px"><span><b>'+esc(r.title)+'</b><br><small>'+esc(r.sub)+'</small></span><span class="pill '+r.color+'">'+r.type+'</span></div>').join('')+'</div>';box.querySelectorAll('.pos-res').forEach(el=>el.addEventListener('click',()=>applyPOSResult(list[Number(el.dataset.idx)])))}
let POS_RES=[],POS_SEL=-1;
function applyPOSResult(r){if(!r)return;const box=$('posDynamicResults');if(box)box.innerHTML='';const inp=$('posDynamicSearch');if(inp)inp.value='';POS_SEL=-1;if(r.type==='Product'){const pp=ALL_PRODUCTS.find(x=>x.id===r.id);if(pp){addToCart(pp,1);focusPOS()}}else if(r.type==='Customer'){if($('saleCustName'))$('saleCustName').value=r.data.name||'';if($('saleCustPhone'))$('saleCustPhone').value=r.data.phone||'';checkPrevDue();toast('Customer selected: '+r.title,'success');focusPOS()}else if(r.type==='Sale'){navTo('sales');loadSalesHistory();toast('Invoice '+r.title,'info')}else if(r.type==='Repair'){navTo('repairing');toast('Repair: '+r.title,'info')}}
async function loadSaleProducts(){ensurePOSSearch();try{const{data}=await supabase.from('products').select('*').order('name');ALL_PRODUCTS=data||[];const cats=[...new Set(ALL_PRODUCTS.map(pp=>pp.category).filter(Boolean))];const cf=$('saleCategoryFilter');if(cf)cf.innerHTML='<option value="">- All Categories -</option>'+cats.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('');const sel=$('saleProductSelect');if(sel)sel.innerHTML='<option value="">- Choose Product -</option>'+ALL_PRODUCTS.map(pp=>'<option value="'+pp.id+'">'+esc(pp.name)+' - '+fmt(pp.sale_price)+' (Stock: '+pp.quantity+')</option>').join('');const{data:cust}=await supabase.from('customers').select('id,name,phone').order('name');ALL_CUSTOMERS=cust||[];const dl=$('posCustomerOptions');if(dl)dl.innerHTML=ALL_CUSTOMERS.map(c=>'<option value="'+esc(c.name)+'">').join('');}catch(e){console.warn(e.message)}renderCart();bindPOSOnce()}
let POS_BOUND=false;
function bindPOSOnce(){if(POS_BOUND)return;POS_BOUND=true;const dyn=ensurePOSSearch();if(dyn){dyn.addEventListener('input',()=>{const q=dyn.value.trim().toLowerCase();if(q.length<2){renderPOSResults([]);return}const out=[];ALL_PRODUCTS.filter(pp=>(pp.name||'').toLowerCase().includes(q)||(pp.brand||'').toLowerCase().includes(q)||(pp.category||'').toLowerCase().includes(q)||(pp.imei_1||'').includes(q)||(pp.imei_2||'').includes(q)||(pp.barcode||'').includes(q)).slice(0,6).forEach(pp=>out.push({type:'Product',color:'blue',title:pp.name,sub:(pp.brand||'')+' | '+fmt(pp.sale_price)+' | Stock '+pp.quantity,id:pp.id}));ALL_CUSTOMERS.filter(c=>(c.name||'').toLowerCase().includes(q)||(c.phone||'').includes(q)).slice(0,3).forEach(c=>out.push({type:'Customer',color:'purple',title:c.name,sub:c.phone||'',data:c}));POS_RES=out;renderPOSResults(out)});dyn.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();POS_SEL=Math.min(POS_SEL+1,POS_RES.length-1)}else if(e.key==='ArrowUp'){e.preventDefault();POS_SEL=Math.max(POS_SEL-1,0)}else if(e.key==='Enter'){e.preventDefault();if(POS_SEL>=0)applyPOSResult(POS_RES[POS_SEL]);else if(POS_RES.length)applyPOSResult(POS_RES[0]);else if(dyn.value.trim()){const pp=ALL_PRODUCTS.find(x=>bmNorm(x.name)===bmNorm(dyn.value));if(pp)addToCart(pp,1)}}else if(e.key==='Escape'){renderPOSResults([])}})}
const bar=$('posBarcodeInput');bar?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const v=bar.value.trim();if(!v)return;const pp=ALL_PRODUCTS.find(x=>x.imei_1===v||x.imei_2===v||x.barcode===v||bmNorm(x.name)===bmNorm(v));if(pp){addToCart(pp,1);bar.value='';focusPOS()}else toast('Barcode / IMEI nahi mila: '+v,'error')}});
const srch=$('posProductSearch');srch?.addEventListener('input',()=>{const q=srch.value.trim().toLowerCase();const sel=$('saleProductSelect');if(!sel)return;let list=ALL_PRODUCTS.filter(pp=>(pp.name||'').toLowerCase().includes(q)||(pp.brand||'').toLowerCase().includes(q));const cat=$('saleCategoryFilter')?.value||'';if(cat)list=list.filter(pp=>pp.category===cat);sel.innerHTML='<option value="">- Choose Product -</option>'+list.map(pp=>'<option value="'+pp.id+'">'+esc(pp.name)+' - '+fmt(pp.sale_price)+' (Stock: '+pp.quantity+')</option>').join('')});
$('btnAddToCart')?.addEventListener('click',()=>{const id=$('saleProductSelect')?.value;if(!id)return toast('Product select karo','error');const pp=ALL_PRODUCTS.find(x=>x.id===id);if(pp)addToCart(pp,1);focusPOS()});
$('saleCustName')?.addEventListener('change',checkPrevDue);$('saleCustName')?.addEventListener('input',()=>{const m=ALL_CUSTOMERS.find(c=>c.name===$('saleCustName').value);if(m&&$('saleCustPhone'))$('saleCustPhone').value=m.phone||'';checkPrevDue()});
$('saleDiscount')?.addEventListener('input',renderCart);$('saleDiscountType')?.addEventListener('change',renderCart);$('posTaxRate')?.addEventListener('input',renderCart);$('posTaxEnabled')?.addEventListener('change',renderCart);$('salePaid')?.addEventListener('input',renderCart);$('salePaymentMethod')?.addEventListener('change',()=>{const m=$('salePaymentMethod').value;if(m==='Udhar / Credit'&&$('salePaid'))$('salePaid').value=0;renderCart()})}
function addToCart(pp,qty){qty=qty||1;if(Number(pp.quantity||0)<=0)return toast('Stock khatam: '+pp.name,'error');const ex=CART.find(i=>i.id===pp.id);if(ex){if(ex.qty+qty>Number(pp.quantity||0))return toast('Stock se zyada!','error');ex.qty+=qty}else CART.push({id:pp.id,name:pp.name,price:Number(pp.sale_price||0),cost:Number(pp.purchase_price||0),qty,lineDisc:0,imei:pp.imei_1||''});renderCart();toast('Added: '+pp.name,'success')}
window.setQty=(id,q)=>{const it=CART.find(i=>i.id===id);if(!it)return;it.qty=Math.max(1,Number(q)||1);renderCart()};
window.removeCartItem=id=>{CART=CART.filter(i=>i.id!==id);renderCart()};
window.setLineDisc=(id,v)=>{const it=CART.find(i=>i.id===id);if(it){it.lineDisc=Number(v)||0;renderCart()}};
function calcCart(){const sub=CART.reduce((a,i)=>a+i.price*i.qty,0);const lineDisc=CART.reduce((a,i)=>a+(Number(i.lineDisc)||0),0);const discType=$('saleDiscountType')?.value||'amt';const discRaw=Number($('saleDiscount')?.value||0);const billDisc=discType==='pct'?Math.round((sub-lineDisc)*discRaw/100):discRaw;const taxOn=$('posTaxEnabled')?.value==='true'||$('posTaxEnabled')?.checked===true;const taxRate=Number($('posTaxRate')?.value||0);const tax=taxOn?Math.round((sub-lineDisc-billDisc)*taxRate/100):0;const total=Math.max(0,sub-lineDisc-billDisc+tax);return{sub,lineDisc,billDisc,tax,total}}
function renderCart(){const box=$('cartItems');if(box){if(!CART.length)box.innerHTML='<div class="empty">Cart is empty</div>';else box.innerHTML='<table class="cart-mini"><thead><tr><th>Item</th><th class="num">Qty</th><th class="num">Price</th><th class="num">Total</th><th></th></tr></thead><tbody>'+CART.map(i=>'<tr><td><b>'+esc(i.name)+'</b><br><small>Disc <input type="number" value="'+i.lineDisc+'" style="width:60px" onchange="window.setLineDisc(\''+i.id+'\',this.value)"></small></td><td class="num"><button class="qty-btn" onclick="window.setQty(\''+i.id+'\','+(i.qty-1)+')">-</button> '+i.qty+' <button class="qty-btn" onclick="window.setQty(\''+i.id+'\','+(i.qty+1)+')">+</button></td><td class="num">'+fmt(i.price)+'</td><td class="num">'+fmt(i.price*i.qty-i.lineDisc)+'</td><td><button class="qty-btn" onclick="window.removeCartItem(\''+i.id+'\')">x</button></td></tr>').join('')+'</tbody></table>'}const c=calcCart();if($('cartSubtotal'))$('cartSubtotal').textContent=fmt(c.sub);if($('cartLineDisc'))$('cartLineDisc').textContent=fmt(c.lineDisc);if($('cartBillDisc'))$('cartBillDisc').textContent=fmt(c.billDisc);if($('cartTax'))$('cartTax').textContent=fmt(c.tax);if($('cartTaxRow'))$('cartTaxRow').style.display=c.tax?'flex':'none';if($('cartTotal'))$('cartTotal').textContent=fmt(c.total);const paid=Number($('salePaid')?.value||0);const warn=$('udharWarning');if(warn){const bal=c.total-paid;if(c.total>0&&paid<c.total){warn.style.display='block';warn.innerHTML='Udhar: <b>'+fmt(bal)+'</b> — Paid se kam hai, baqi udhar me jayega. Customer ka naam zaroor likhein.'}else warn.style.display='none'}}
window.setPaidFull=()=>{const c=calcCart();if($('salePaid'))$('salePaid').value=c.total;renderCart()};
window.setPaidZero=()=>{if($('salePaid'))$('salePaid').value=0;if($('salePaymentMethod'))$('salePaymentMethod').value='Udhar / Credit';renderCart()};
async function checkPrevDue(){const name=$('saleCustName')?.value.trim();if(!name){if($('previousDueBox'))$('previousDueBox').style.display='none';return}try{const{data}=await supabase.from('sales').select('balance').eq('customer_name',name).gt('balance',0);const tot=(data||[]).reduce((a,r)=>a+Number(r.balance||0),0);if($('previousDueBox'))$('previousDueBox').style.display=tot?'block':'none';if($('previousDueAmount'))$('previousDueAmount').textContent=fmt(tot)}catch(e){}}
$('btnHoldSale')?.addEventListener('click',()=>{if(!CART.length)return toast('Cart khaali hai','error');HELD_CARTS.push({cart:[...CART],cust:$('saleCustName')?.value||'',phone:$('saleCustPhone')?.value||'',time:new Date().toLocaleTimeString('en-PK')});CART=[];if($('saleCustName'))$('saleCustName').value='';if($('saleCustPhone'))$('saleCustPhone').value='';renderCart();toast('Sale held ('+HELD_CARTS.length+')','success');focusPOS()});
$('btnResumeSale')?.addEventListener('click',()=>{if(!HELD_CARTS.length)return toast('Koi held sale nahi','error');const h=HELD_CARTS.pop();CART=h.cart;if($('saleCustName'))$('saleCustName').value=h.cust;if($('saleCustPhone'))$('saleCustPhone').value=h.phone;renderCart();toast('Held sale resumed','success');focusPOS()});
$('btnSplitPayment')?.addEventListener('click',openPaymentSplitModal);
function openPaymentSplitModal(){const c=calcCart();const body='<div class="form-grid"><div class="field"><label>Total</label><input value="'+c.total+'" readonly></div><div class="field"><label>Cash</label><input id="splitCash" type="number" value="0"></div><div class="field"><label>Card</label><input id="splitCard" type="number" value="0"></div><div class="field"><label>Easypaisa / JazzCash</label><input id="splitWallet" type="number" value="0"></div><div class="field full"><label>Udhar (baqi auto)</label><input id="splitSumAmt" value="0" readonly></div></div><p style="font-size:12px;color:var(--muted)">Cash+Card+Wallet = Paid. Baqi Udhar me jayega.</p>';openModal('Split Payment',body,async()=>{const paid=(Number($('splitCash').value)||0)+(Number($('splitCard').value)||0)+(Number($('splitWallet').value)||0);if($('salePaid'))$('salePaid').value=paid;closeModal();renderCart();toast('Split set: Paid '+fmt(paid),'success')},'Apply Split');setTimeout(()=>{['splitCash','splitCard','splitWallet'].forEach(id=>{$(id)?.addEventListener('input',()=>{const s=(Number($('splitCash')?.value)||0)+(Number($('splitCard')?.value)||0)+(Number($('splitWallet')?.value)||0);if($('splitSumAmt'))$('splitSumAmt').value=s})})},100)}
async function saveSale(){if(!CART.length)return toast('Cart khaali hai','error');const c=calcCart();const custName=$('saleCustName')?.value.trim()||'Walk-in';const custPhone=$('saleCustPhone')?.value.trim()||'';const method=$('salePaymentMethod')?.value||'Cash';let paid=Number($('salePaid')?.value||0);if(method==='Udhar / Credit')paid=0;const balance=Math.max(0,c.total-paid);if(balance>0&&custName==='Walk-in'){if(!confirm('Udhar Walk-in naam par jayega. Continue?'))return}const invoice='INV-'+Date.now().toString().slice(-6);const btn=$('btnSaveSale');btn.disabled=true;try{const{data:sale,error}=await supabase.from('sales').insert({invoice_no:invoice,customer_name:custName,customer_phone:custPhone,total:c.total,paid,balance,discount:c.billDisc+ c.lineDisc,tax:c.tax,payment_method:method}).select().single();if(error)throw new Error(error.message);const items=CART.map(i=>({sale_id:sale.id,product_id:i.id,quantity:i.qty,unit_price:i.price,line_total:i.price*i.qty-Number(i.lineDisc||0)}));const{error:e2}=await supabase.from('sale_items').insert(items);if(e2)throw new Error(e2.message);for(const i of CART){const pp=ALL_PRODUCTS.find(x=>x.id===i.id);if(pp)await supabase.from('products').update({quantity:Math.max(0,Number(pp.quantity||0)-i.qty)}).eq('id',i.id)}let cust=ALL_CUSTOMERS.find(x=>x.name===custName);if(!cust&&custName!=='Walk-in'){const{data:nc}=await supabase.from('customers').insert({name:custName,phone:custPhone,balance:balance}).select().single();cust=nc}else if(cust&&balance>0){await supabase.from('customers').update({balance:Number(cust.balance||0)+balance}).eq('id',cust.id)}await logActivity('CREATE','sales',invoice+' | '+fmt(c.total)+' | '+custName);const printNow=confirm('Sale saved! Receipt print karein?');if(printNow){const useA4=confirm('A4 print? OK = A4, Cancel = Thermal 80mm');const payload={invoice,total:c.total,paid,balance,discount:c.billDisc+c.lineDisc,tax:c.tax,subtotal:c.sub,payment_method:method,customer:custName,phone:custPhone,cashier:CURRENT_NAME,items:CART.map(i=>({product_name:i.name,quantity:i.qty,unit_price:i.price,line_total:i.price*i.qty-Number(i.lineDisc||0)}))};if(useA4)printA4Premium(payload,'sale');else printThermal80mm(payload,'sale')}CART=[];if($('saleCustName'))$('saleCustName').value='';if($('saleCustPhone'))$('saleCustPhone').value='';if($('salePaid'))$('salePaid').value=0;if($('saleDiscount'))$('saleDiscount').value=0;renderCart();loadSaleProducts();loadOverview();loadSalesHistory();toast('Sale saved: '+invoice,'success');focusPOS()}catch(e){toast(e.message,'error')}finally{btn.disabled=false}}
$('btnSaveSale')?.addEventListener('click',saveSale);
$('btnSalesHistory')?.addEventListener('click',()=>{const box=$('salesHistoryBox');box.hidden=!box.hidden;if(!box.hidden)loadSalesHistory()});
$('btnRefreshSales')?.addEventListener('click',loadSalesHistory);
async function loadSalesHistory(){try{const{data}=await supabase.from('sales').select('*').order('created_at',{ascending:false}).limit(100);const t=$('salesHistoryTable');if(!t)return;t.innerHTML=(data||[]).length?'<table class="data"><thead><tr><th>Invoice</th><th>Customer</th><th class="num">Total</th><th class="num">Paid</th><th class="num">Balance</th><th>Method</th><th>Date</th><th>Actions</th></tr></thead><tbody>'+data.map(s=>'<tr><td><b>'+esc(s.invoice_no)+'</b></td><td>'+esc(s.customer_name||'Walk-in')+'</td><td class="num">'+fmt(s.total)+'</td><td class="num">'+fmt(s.paid)+'</td><td class="num">'+fmt(s.balance)+'</td><td>'+esc(s.payment_method||'')+'</td><td><small>'+new Date(s.created_at).toLocaleDateString('en-PK')+'</small></td><td><button class="btn btn-sm" onclick="window.reprintSale(\''+s.id+'\')">Print</button> <button class="btn btn-sm btn-danger" onclick="window.deleteSale(\''+s.id+'\')">Del</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">No sales.</div>'}catch(e){}}
window.reprintSale=async id=>{const{data:s}=await supabase.from('sales').select('*').eq('id',id).single();if(!s)return;const{data:items}=await supabase.from('sale_items').select('*,products(name)').eq('sale_id',id);printThermal80mm({invoice:s.invoice_no,total:s.total,paid:s.paid,balance:s.balance,discount:s.discount,tax:s.tax,subtotal:s.total,payment_method:s.payment_method,customer:s.customer_name,phone:s.customer_phone,cashier:CURRENT_NAME,items:(items||[]).map(i=>({product_name:i.products?.name||'Item',quantity:i.quantity,unit_price:i.unit_price,line_total:i.line_total}))},'sale')};
window.deleteSale=async id=>{if(!checkPermission('delete'))return;if(!confirm('Delete sale + stock wapas?'))return;const{data:items}=await supabase.from('sale_items').select('*').eq('sale_id',id);for(const it of items||[]){const{data:pp}=await supabase.from('products').select('quantity').eq('id',it.product_id).single();if(pp)await supabase.from('products').update({quantity:Number(pp.quantity||0)+Number(it.quantity||0)}).eq('id',it.product_id)}await supabase.from('sale_items').delete().eq('sale_id',id);await supabase.from('sales').delete().eq('id',id);toast('Sale deleted, stock restored');loadSalesHistory();loadOverview()};

// =====================================================
// REPAIRING + CUSTOMERS + SUPPLIERS
