async function loadRepairs(){try{const q=$('repairSearch')?.value?.trim().toLowerCase()||'';const st=$('repairStatusFilter')?.value||'';const{data}=await supabase.from('repairs').select('*').order('created_at',{ascending:false}).limit(200);let list=data||[];if(q)list=list.filter(r=>(r.customer_name||'').toLowerCase().includes(q)||(r.device||'').toLowerCase().includes(q)||(r.phone||'').includes(q)||(r.slip_no||'').toLowerCase().includes(q));if(st)list=list.filter(r=>r.status===st);const t=$('repairsTable');if(!t)return;t.innerHTML=list.length?'<table class="data"><thead><tr><th>Slip</th><th>Customer</th><th>Device</th><th>Issue</th><th class="num">Charge</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+list.map(r=>'<tr><td><b>'+esc(r.slip_no||'')+'</b></td><td>'+esc(r.customer_name||'')+'<br><small>'+esc(r.phone||'')+'</small></td><td>'+esc(r.device||'')+'</td><td>'+esc(r.issue||'')+'</td><td class="num">'+fmt(r.charge||0)+'</td><td><span class="pill '+(r.status==='Completed'?'green':r.status==='In Progress'?'orange':'blue')+'">'+esc(r.status||'Pending')+'</span></td><td><button class="btn btn-sm" onclick="window.printRepair(\''+r.id+'\')">Print</button> <button class="btn btn-sm" onclick="window.editRepair(\''+r.id+'\')">Edit</button> <button class="btn btn-sm btn-success" onclick="window.completeRepair(\''+r.id+'\')">Done</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">No repairs.</div>'}catch(e){}}
$('repairSearch')?.addEventListener('input',loadRepairs);$('repairStatusFilter')?.addEventListener('change',loadRepairs);
$('btnAddRepair')?.addEventListener('click',()=>openRepairModal());
function openRepairModal(r){r=r||null;const body='<div class="form-grid"><div class="field"><label>Customer Name *</label><input id="rpCust" value="'+esc(r?.customer_name||'')+'"></div><div class="field"><label>Phone</label><input id="rpPhone" value="'+esc(r?.phone||'')+'"></div><div class="field"><label>Device *</label><input id="rpDevice" placeholder="e.g. iPhone 13 / Samsung A32" value="'+esc(r?.device||'')+'"></div><div class="field"><label>Issue *</label><input id="rpIssue" value="'+esc(r?.issue||'')+'"></div><div class="field"><label>Charge</label><input id="rpCharge" type="number" value="'+(r?.charge||0)+'"></div><div class="field"><label>Advance</label><input id="rpAdv" type="number" value="'+(r?.advance||0)+'"></div><div class="field"><label>Status</label><select id="rpStatus"><option>Pending</option><option>In Progress</option><option>Completed</option><option>Delivered</option></select></div><div class="field full"><label>Notes</label><input id="rpNotes" value="'+esc(r?.notes||'')+'"></div></div>';openModal(r?'Edit Repair':'New Repair',body,async()=>{const payload={customer_name:$('rpCust').value.trim(),phone:$('rpPhone').value.trim(),device:$('rpDevice').value.trim(),issue:$('rpIssue').value.trim(),charge:Number($('rpCharge').value)||0,advance:Number($('rpAdv').value)||0,status:$('rpStatus').value,notes:$('rpNotes').value.trim()||null};if(!payload.customer_name||!payload.device)throw new Error('Customer + Device required');if(r)await supabase.from('repairs').update(payload).eq('id',r.id);else{const{data,error}=await supabase.from('repairs').insert({...payload,slip_no:'RP-'+Date.now().toString().slice(-6)}).select().single();if(error)throw new Error(error.message);if(confirm('Repair slip print karein?'))printRepairSlip(data)}await logActivity(r?'EDIT':'CREATE','repairing',payload.device);closeModal();toast('Saved','success');loadRepairs()},'Save')}
function printRepairSlip(r){printThermal80mm({invoice:r.slip_no,total:r.charge,paid:r.advance,balance:Number(r.charge||0)-Number(r.advance||0),customer:r.customer_name,phone:r.phone,items:[{product_name:r.device+' - '+r.issue,quantity:1,unit_price:r.charge,line_total:r.charge}],payment_method:'Repair'},'repair')}
window.printRepair=async id=>{const{data}=await supabase.from('repairs').select('*').eq('id',id).single();if(data)printRepairSlip(data)};
window.editRepair=async id=>{const{data}=await supabase.from('repairs').select('*').eq('id',id).single();if(data)openRepairModal(data)};
window.completeRepair=async id=>{await supabase.from('repairs').update({status:'Completed'}).eq('id',id);toast('Completed','success');loadRepairs()};
async function loadCustomers(){try{const q=$('custSearch')?.value?.trim().toLowerCase()||'';const{data}=await supabase.from('customers').select('*').order('name');let list=data||[];if(q)list=list.filter(c=>(c.name||'').toLowerCase().includes(q)||(c.phone||'').includes(q));ALL_CUSTOMERS=list;const t=$('customersTable');if(!t)return;t.innerHTML=list.length?'<table class="data"><thead><tr><th><input type="checkbox" onchange="toggleAllCust(this)"></th><th>Name</th><th>Phone</th><th class="num">Balance</th><th>Total Purchases</th><th>Actions</th></tr></thead><tbody>'+list.map(c=>'<tr><td><input type="checkbox" class="cust-check" value="'+c.id+'" onchange="updateCustBulk()"></td><td><b>'+esc(c.name)+'</b></td><td>'+esc(c.phone||'-')+'</td><td class="num" style="color:'+(Number(c.balance||0)>0?'#DC2626':'#059669')+'">'+fmt(c.balance||0)+'</td><td class="num">'+fmt(c.total_purchases||0)+'</td><td><button class="btn btn-sm" onclick="window.viewCustomerLedger(\''+c.id+'\')">Ledger</button> <button class="btn btn-sm" onclick="window.editCustomer(\''+c.id+'\')">Edit</button> <button class="btn btn-sm btn-danger" onclick="window.deleteCustomer(\''+c.id+'\')">Del</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">No customers.</div>'}catch(e){}}
$('custSearch')?.addEventListener('input',loadCustomers);$('btnAddCustomer')?.addEventListener('click',()=>openCustomerModal());
window.toggleAllCust=cb=>{document.querySelectorAll('.cust-check').forEach(c=>c.checked=cb.checked);updateCustBulk()};
function updateCustBulk(){const n=document.querySelectorAll('.cust-check:checked').length;const bar=$('custBulkBar');if(bar)bar.style.display=n?'flex':'none';if($('custSelCount'))$('custSelCount').textContent=n}
function openCustomerModal(c){c=c||null;const body='<div class="form-grid"><div class="field"><label>Name *</label><input id="cuName" value="'+esc(c?.name||'')+'"></div><div class="field"><label>Phone</label><input id="cuPhone" value="'+esc(c?.phone||'')+'"></div><div class="field full"><label>Address</label><input id="cuAddr" value="'+esc(c?.address||'')+'"></div></div>';openModal(c?'Edit Customer':'Add Customer',body,async()=>{const payload={name:$('cuName').value.trim(),phone:$('cuPhone').value.trim()||null,address:$('cuAddr').value.trim()||null};if(!payload.name)throw new Error('Name required');if(c)await supabase.from('customers').update(payload).eq('id',c.id);else await supabase.from('customers').insert(payload);closeModal();toast('Saved','success');loadCustomers()},'Save')}
window.editCustomer=async id=>{const c=ALL_CUSTOMERS.find(x=>x.id===id);if(c)openCustomerModal(c)};
window.deleteCustomer=async id=>{if(!checkPermission('delete'))return;if(!confirm('Delete customer?'))return;await supabase.from('customers').delete().eq('id',id);toast('Deleted');loadCustomers()};
window.viewCustomerLedger=async id=>{const c=ALL_CUSTOMERS.find(x=>x.id===id);if(!c)return;const{data}=await supabase.from('sales').select('*').eq('customer_name',c.name).order('created_at',{ascending:false});const tot=(data||[]).reduce((a,s)=>a+Number(s.balance||0),0);openModal('Ledger - '+c.name,'<p>Phone: '+esc(c.phone||'-')+' | Total Udhar: <b style="color:#DC2626">'+fmt(tot)+'</b></p><table class="data"><thead><tr><th>Invoice</th><th class="num">Total</th><th class="num">Paid</th><th class="num">Balance</th><th>Date</th></tr></thead><tbody>'+((data||[]).map(s=>'<tr><td>'+esc(s.invoice_no)+'</td><td class="num">'+fmt(s.total)+'</td><td class="num">'+fmt(s.paid)+'</td><td class="num">'+fmt(s.balance)+'</td><td>'+new Date(s.created_at).toLocaleDateString('en-PK')+'</td></tr>').join('')||'<tr><td colspan="5">No sales</td></tr>')+'</tbody></table><div style="display:flex;gap:8px;margin-top:14px"><button class="btn btn-primary" onclick="window.printCustomerLedger(\''+c.id+'\')">Print A4</button><button class="btn btn-success" onclick="window.sendLedgerWhatsApp(\''+c.id+'\')">WhatsApp</button></div>',async()=>closeModal(),'Close')};
window.printCustomerLedger=async id=>{const c=ALL_CUSTOMERS.find(x=>x.id===id);if(!c)return;const{data}=await supabase.from('sales').select('*').eq('customer_name',c.name);printA4Premium({invoice:'LEDGER-'+c.name,total:(data||[]).reduce((a,s)=>a+Number(s.total||0),0),paid:(data||[]).reduce((a,s)=>a+Number(s.paid||0),0),balance:(data||[]).reduce((a,s)=>a+Number(s.balance||0),0),customer:c.name,phone:c.phone,items:(data||[]).map(s=>({product_name:s.invoice_no+' | '+new Date(s.created_at).toLocaleDateString('en-PK'),quantity:1,unit_price:s.total,line_total:s.total}))},'sale')};
window.sendLedgerWhatsApp=id=>{const c=ALL_CUSTOMERS.find(x=>x.id===id);if(!c||!c.phone)return toast('Phone nahi hai','error');const msg='Assalam-o-Alaikum '+c.name+', '+SHOP.name+' se aapka baqaya udhar '+fmt(c.balance||0)+' hai. Please jald clear kar dein. Shukriya!';window.open('https://wa.me/92'+String(c.phone).replace(/\D/g,'').slice(-10)+'?text='+encodeURIComponent(msg),'_blank')};
async function loadSuppliers(){try{const q=$('supplierSearch')?.value?.trim().toLowerCase()||'';const cat=$('supplierCategoryFilter')?.value||'';const{data}=await supabase.from('suppliers').select('*').order('name');let list=data||[];if(q)list=list.filter(s=>(s.name||'').toLowerCase().includes(q)||(s.phone||'').includes(q));if(cat)list=list.filter(s=>s.category===cat);ALL_SUPPLIERS=list;const t=$('suppliersTable');if(!t)return;t.innerHTML=list.length?'<table class="data"><thead><tr><th>Name</th><th>Phone</th><th>Category</th><th class="num">Balance</th><th>Actions</th></tr></thead><tbody>'+list.map(s=>'<tr><td><b>'+esc(s.name)+'</b></td><td>'+esc(s.phone||'-')+'</td><td>'+esc(s.category||'-')+'</td><td class="num">'+fmt(s.balance||0)+'</td><td><button class="btn btn-sm" onclick="window.editSupplier(\''+s.id+'\')">Edit</button> <button class="btn btn-sm btn-danger" onclick="window.deleteSupplier(\''+s.id+'\')">Del</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">No suppliers.</div>'}catch(e){}}
$('supplierSearch')?.addEventListener('input',loadSuppliers);$('supplierCategoryFilter')?.addEventListener('change',loadSuppliers);$('btnAddSupplier')?.addEventListener('click',()=>openSupplierModal());
function openSupplierModal(s){s=s||null;const body='<div class="form-grid"><div class="field"><label>Name *</label><input id="suName" value="'+esc(s?.name||'')+'"></div><div class="field"><label>Phone</label><input id="suPhone" value="'+esc(s?.phone||'')+'"></div><div class="field"><label>Category</label><input id="suCat" value="'+esc(s?.category||'')+'"></div><div class="field"><label>Balance</label><input id="suBal" type="number" value="'+(s?.balance||0)+'"></div></div>';openModal(s?'Edit Supplier':'Add Supplier',body,async()=>{const payload={name:$('suName').value.trim(),phone:$('suPhone').value.trim()||null,category:$('suCat').value.trim()||null,balance:Number($('suBal').value)||0};if(!payload.name)throw new Error('Name required');if(s)await supabase.from('suppliers').update(payload).eq('id',s.id);else await supabase.from('suppliers').insert(payload);closeModal();toast('Saved','success');loadSuppliers()},'Save')}
window.editSupplier=async id=>{const s=ALL_SUPPLIERS.find(x=>x.id===id);if(s)openSupplierModal(s)};
window.deleteSupplier=async id=>{if(!checkPermission('delete'))return;if(!confirm('Delete supplier?'))return;await supabase.from('suppliers').delete().eq('id',id);toast('Deleted');loadSuppliers()};

// =====================================================
// CREDIT / UDHAR - FULLY WORKING + PRINT
// =====================================================
let CREDIT_FILTER={date:'all',status:'all'};
async function loadCredit(){try{const{data}=await supabase.from('sales').select('*').gt('balance',0).order('created_at',{ascending:false});let list=data||[];const today=bmTodayISO();if(CREDIT_FILTER.date==='today')list=list.filter(x=>x.created_at?.slice(0,10)===today);if(CREDIT_FILTER.date==='week'){const d=new Date();d.setDate(d.getDate()-7);list=list.filter(x=>new Date(x.created_at)>=d)}if(CREDIT_FILTER.date==='month')list=list.filter(x=>x.created_at?.slice(0,7)===today.slice(0,7));const byCust={};list.forEach(x=>{const k=x.customer_name||'Walk-in';if(!byCust[k])byCust[k]={name:k,total:0,items:[]};byCust[k].total+=Number(x.balance||0);byCust[k].items.push(x)});const sum=Object.values(byCust).sort((a,b)=>b.total-a.total);if($('creditSummaryTable'))$('creditSummaryTable').innerHTML=sum.length?'<table class="data"><thead><tr><th>Customer</th><th class="num">Total Udhar</th><th>Invoices</th><th>Actions</th></tr></thead><tbody>'+sum.map((c,i)=>'<tr><td><b>'+esc(c.name)+'</b></td><td class="num" style="color:#DC2626;font-weight:800">'+fmt(c.total)+'</td><td>'+c.items.length+'</td><td style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn btn-sm btn-success" onclick="window.receiveUdhar(\''+esc(c.name)+'\')">Receive</button><button class="btn btn-sm" onclick="window.printUdharCustomer(\''+esc(c.name)+'\')">A4 Print</button><button class="btn btn-sm" onclick="window.printUdharThermal(\''+esc(c.name)+'\')">Thermal</button><button class="btn btn-sm btn-success" onclick="window.sendLedgerWhatsAppByName(\''+esc(c.name)+'\')">WhatsApp</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">Koi udhar nahi. Alhamdulillah!</div>';if($('creditTable'))$('creditTable').innerHTML=list.length?'<table class="data"><thead><tr><th>Invoice</th><th>Customer</th><th class="num">Total</th><th class="num">Paid</th><th class="num">Balance</th><th>Date</th><th>Action</th></tr></thead><tbody>'+list.map(x=>'<tr><td>'+esc(x.invoice_no)+'</td><td>'+esc(x.customer_name||'Walk-in')+'</td><td class="num">'+fmt(x.total)+'</td><td class="num">'+fmt(x.paid)+'</td><td class="num">'+fmt(x.balance)+'</td><td>'+new Date(x.created_at).toLocaleDateString('en-PK')+'</td><td><button class="btn btn-sm btn-success" onclick="window.receiveUdharInvoice(\''+x.id+'\')">Receive</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">Koi udhar nahi.</div>';const{data:rec}=await supabase.from('sales').select('*').order('created_at',{ascending:false}).limit(20);if($('recoveriesTable'))$('recoveriesTable').innerHTML=(rec||[]).length?'<table class="data"><thead><tr><th>Invoice</th><th>Customer</th><th class="num">Paid</th><th>Date</th></tr></thead><tbody>'+rec.slice(0,10).map(x=>'<tr><td>'+esc(x.invoice_no)+'</td><td>'+esc(x.customer_name||'')+'</td><td class="num">'+fmt(x.paid)+'</td><td>'+new Date(x.created_at).toLocaleDateString('en-PK')+'</td></tr>').join('')+'</tbody></table>':'<div class="empty">No recoveries.</div>'}catch(e){if($('creditTable'))$('creditTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
document.querySelectorAll('#creditDateTabs button, #creditStatusTabs button').forEach(b=>b.addEventListener('click',()=>{b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');const t=b.textContent.toLowerCase();if(['all','today','week','month'].includes(t))CREDIT_FILTER.date=t;else CREDIT_FILTER.status=t;loadCredit()}));
window.receiveUdhar=async name=>{const amt=Number(prompt(name+' se kitni recovery hui?','0')||0);if(amt<=0)return;const{data}=await supabase.from('sales').select('*').eq('customer_name',name).gt('balance',0).order('created_at');let left=amt;for(const s of data||[]){if(left<=0)break;const pay=Math.min(left,Number(s.balance||0));await supabase.from('sales').update({paid:Number(s.paid||0)+pay,balance:Number(s.balance||0)-pay}).eq('id',s.id);left-=pay}const{data:cust}=await supabase.from('customers').select('*').eq('name',name).maybeSingle();if(cust)await supabase.from('customers').update({balance:Math.max(0,Number(cust.balance||0)-amt)}).eq('id',cust.id);await logActivity('RECEIVE','credit',name+' | '+fmt(amt));toast('Recovery saved: '+fmt(amt),'success');loadCredit();loadOverview()};
window.receiveUdharInvoice=async id=>{const amt=Number(prompt('Kitni recovery?','0')||0);if(amt<=0)return;const{data:s}=await supabase.from('sales').select('*').eq('id',id).single();if(!s)return;await supabase.from('sales').update({paid:Number(s.paid||0)+amt,balance:Math.max(0,Number(s.balance||0)-amt)}).eq('id',id);toast('Saved','success');loadCredit()};
window.printUdharCustomer=async name=>{const{data}=await supabase.from('sales').select('*').eq('customer_name',name).gt('balance',0);if(!data?.length)return toast('Koi udhar nahi','error');printA4Premium({invoice:'UDHAR-'+name,total:data.reduce((a,s)=>a+Number(s.total||0),0),paid:data.reduce((a,s)=>a+Number(s.paid||0),0),balance:data.reduce((a,s)=>a+Number(s.balance||0),0),customer:name,items:data.map(s=>({product_name:s.invoice_no+' | '+new Date(s.created_at).toLocaleDateString('en-PK'),quantity:1,unit_price:s.total,line_total:s.total}))},'sale')};
window.printUdharThermal=async name=>{const{data}=await supabase.from('sales').select('*').eq('customer_name',name).gt('balance',0);if(!data?.length)return toast('Koi udhar nahi','error');printThermal80mm({invoice:'UDHAR-'+name,total:data.reduce((a,s)=>a+Number(s.total||0),0),paid:data.reduce((a,s)=>a+Number(s.paid||0),0),balance:data.reduce((a,s)=>a+Number(s.balance||0),0),customer:name,items:data.map(s=>({product_name:s.invoice_no,quantity:1,unit_price:s.total,line_total:s.total}))},'sale')};
window.sendLedgerWhatsAppByName=name=>{const c=ALL_CUSTOMERS.find(x=>x.name===name);if(c)window.sendLedgerWhatsApp(c.id);else{const msg='Assalam-o-Alaikum '+name+', '+SHOP.name+' se udhar baqaya hai. Shukriya!';toast('Customer phone nahi mila - manual WhatsApp karein','error')}};
window.printAllUdhar=async()=>{const{data}=await supabase.from('sales').select('*').gt('balance',0).order('customer_name');if(!data?.length)return toast('Koi udhar nahi','error');const by={};data.forEach(s=>{by[s.customer_name||'Walk-in']=(by[s.customer_name||'Walk-in']||0)+Number(s.balance||0)});printA4Premium({invoice:'ALL-UDHAR-'+Date.now().toString().slice(-6),total:Object.values(by).reduce((a,b)=>a+b,0),paid:0,balance:Object.values(by).reduce((a,b)=>a+b,0),customer:'Sab Customers',items:Object.entries(by).map(([n,v])=>({product_name:n,quantity:1,unit_price:v,line_total:v}))},'sale')};
window.exportUdhar=()=>{supabase.from('sales').select('*').gt('balance',0).then(({data})=>{let csv='Customer,Invoice,Total,Paid,Balance,Date\n';(data||[]).forEach(s=>csv+='"'+(s.customer_name||'')+'","'+s.invoice_no+'",'+s.total+','+s.paid+','+s.balance+','+new Date(s.created_at).toLocaleDateString()+'\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='Udhar_'+Date.now()+'.csv';a.click();toast('Udhar exported!','success')})};
// =====================================================
// EXPENSES - FULLY WORKING + BUDGET + CHART
// =====================================================
const EXP_CATS=['Shop Rent','Electricity','Internet / WiFi','Staff Salary','Tea / Food','Transport','Repair Cost','Marketing','Stationery','Misc','Other'];
let EXP_FILTER={from:'',to:'',cat:''};
async function loadExpenses(){try{let q=supabase.from('expenses').select('*').order('created_at',{ascending:false});if(EXP_FILTER.from)q=q.gte('created_at',EXP_FILTER.from);if(EXP_FILTER.to)q=q.lte('created_at',EXP_FILTER.to+'T23:59:59');const{data}=await q;let list=data||[];if(EXP_FILTER.cat)list=list.filter(e=>e.category===EXP_FILTER.cat);const today=bmTodayISO(),week=new Date();week.setDate(week.getDate()-7),month=today.slice(0,7);const sum=a=>a.reduce((s,e)=>s+Number(e.amount||0),0);const set=(id,v)=>{if($(id))$(id).textContent=fmt(v)};set('expToday',sum(list.filter(e=>e.created_at?.slice(0,10)===today)));set('expWeek',sum(list.filter(e=>new Date(e.created_at)>=week)));set('expMonth',sum(list.filter(e=>e.created_at?.slice(0,7)===month)));set('expTotal',sum(list));const byCat={};list.forEach(e=>byCat[e.category||'Other']=(byCat[e.category||'Other']||0)+Number(e.amount||0));if($('expCatChart'))$('expCatChart').innerHTML=Object.entries(byCat).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([k,v])=>'<div style="margin-bottom:8px"><div style="display:flex;justify-content:space-between;font-size:12.5px;font-weight:700"><span>'+esc(k)+'</span><span>'+fmt(v)+'</span></div><div class="bar" style="margin-top:4px;height:8px;background:var(--bg-soft);border-radius:20px;overflow:hidden"><i style="display:block;height:100%;background:linear-gradient(90deg,#F59E0B,#EF4444);width:'+Math.round(v/Math.max(1,...Object.values(byCat))*100)+'%"></i></div></div>').join('')||'<div class="empty">No expenses.</div>';if($('expensesTable'))$('expensesTable').innerHTML=list.length?'<table class="data"><thead><tr><th>Date</th><th>Category</th><th>Description</th><th class="num">Amount</th><th>Actions</th></tr></thead><tbody>'+list.map(e=>'<tr><td>'+new Date(e.created_at).toLocaleDateString('en-PK')+'</td><td><span class="pill orange">'+esc(e.category||'Other')+'</span></td><td>'+esc(e.description||'-')+'</td><td class="num" style="color:#DC2626;font-weight:800">'+fmt(e.amount)+'</td><td><button class="btn btn-sm" onclick="window.editExpense(\''+e.id+'\')">Edit</button> <button class="btn btn-sm btn-danger" onclick="window.deleteExpense(\''+e.id+'\')">Del</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">No expenses in this filter.</div>'}catch(e){if($('expensesTable'))$('expensesTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
$('expFilterFrom')?.addEventListener('change',e=>{EXP_FILTER.from=e.target.value;loadExpenses()});$('expFilterTo')?.addEventListener('change',e=>{EXP_FILTER.to=e.target.value;loadExpenses()});$('expFilterCat')?.addEventListener('change',e=>{EXP_FILTER.cat=e.target.value;loadExpenses()});$('btnFilterExpenses')?.addEventListener('click',loadExpenses);$('btnAddExpense')?.addEventListener('click',()=>openExpenseModal());
function openExpenseModal(e){e=e||null;const body='<div class="form-grid"><div class="field"><label>Category *</label><select id="exCat">'+EXP_CATS.map(c=>'<option '+(e?.category===c?'selected':'')+'>'+c+'</option>').join('')+'</select></div><div class="field"><label>Amount *</label><input id="exAmt" type="number" value="'+(e?.amount||'')+'" placeholder="e.g. 5000"></div><div class="field full"><label>Description</label><input id="exDesc" value="'+esc(e?.description||'')+'" placeholder="Kis cheez ka kharcha?"></div><div class="field"><label>Date</label><input id="exDate" type="date" value="'+(e?.created_at?.slice(0,10)||bmTodayISO())+'"></div></div>';openModal(e?'Edit Expense':'Add Expense',body,async()=>{const amt=Number($('exAmt').value)||0;if(amt<=0)throw new Error('Amount > 0 likhein');const payload={category:$('exCat').value,amount:amt,description:$('exDesc').value.trim()||null};if(e){await supabase.from('expenses').update(payload).eq('id',e.id)}else{await supabase.from('expenses').insert(payload)}await logActivity(e?'EDIT':'CREATE','expenses',payload.category+' | '+fmt(amt));closeModal();toast('Saved','success');loadExpenses();loadOverview();loadDailyPL()},'Save')}
window.editExpense=async id=>{const{data}=await supabase.from('expenses').select('*').eq('id',id).single();if(data)openExpenseModal(data)};
window.deleteExpense=async id=>{if(!checkPermission('delete'))return;if(!confirm('Delete expense?'))return;await supabase.from('expenses').delete().eq('id',id);toast('Deleted');loadExpenses()};
window.exportExpenses=()=>{supabase.from('expenses').select('*').order('created_at',{ascending:false}).then(({data})=>{let csv='Date,Category,Description,Amount\n';(data||[]).forEach(e=>csv+=new Date(e.created_at).toLocaleDateString()+',"'+(e.category||'')+'","'+(e.description||'')+'",'+e.amount+'\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='Expenses_'+Date.now()+'.csv';a.click();toast('Exported!','success')})};
// =====================================================
// TRANSACTIONS - FULL LEDGER
// =====================================================
let TX_FILTER={type:'all',from:'',to:'',q:''};
async function loadTransactions(){try{const [sales,purch,exps]=await Promise.all([supabase.from('sales').select('id,invoice_no,total,paid,customer_name,created_at').order('created_at',{ascending:false}).limit(500),supabase.from('purchases').select('id,invoice_no,total,paid,created_at').order('created_at',{ascending:false}).limit(500),supabase.from('expenses').select('id,category,amount,description,created_at').order('created_at',{ascending:false}).limit(500)]);let tx=[];(sales.data||[]).forEach(s=>tx.push({id:s.id,type:'SALE',ref:s.invoice_no,party:s.customer_name||'Walk-in',inAmt:Number(s.paid||0),outAmt:0,date:s.created_at,bal:Number(s.balance||0)}));(purch.data||[]).forEach(p=>tx.push({id:p.id,type:'PURCHASE',ref:p.invoice_no,party:'Supplier',inAmt:0,outAmt:Number(p.paid||0),date:p.created_at,bal:0}));(exps.data||[]).forEach(e=>tx.push({id:e.id,type:'EXPENSE',ref:e.category,party:e.description||'',inAmt:0,outAmt:Number(e.amount||0),date:e.created_at,bal:0}));tx.sort((a,b)=>new Date(b.date)-new Date(a.date));if(TX_FILTER.type!=='all')tx=tx.filter(t=>t.type===TX_FILTER.type);if(TX_FILTER.from)tx=tx.filter(t=>t.date.slice(0,10)>=TX_FILTER.from);if(TX_FILTER.to)tx=tx.filter(t=>t.date.slice(0,10)<=TX_FILTER.to);if(TX_FILTER.q){const q=TX_FILTER.q.toLowerCase();tx=tx.filter(t=>(t.ref||'').toLowerCase().includes(q)||(t.party||'').toLowerCase().includes(q))}const inT=tx.reduce((a,t)=>a+t.inAmt,0),outT=tx.reduce((a,t)=>a+t.outAmt,0);if($('txIn'))$('txIn').textContent=fmt(inT);if($('txOut'))$('txOut').textContent=fmt(outT);if($('txNet'))$('txNet').textContent=fmt(inT-outT);let running=0;const rows=[...tx].reverse().map(t=>{running+=t.inAmt-t.outAmt;return{...t,running}}).reverse();if($('transactionsTable'))$('transactionsTable').innerHTML=rows.length?'<table class="data"><thead><tr><th>Date</th><th>Type</th><th>Ref</th><th>Party</th><th class="num">In</th><th class="num">Out</th><th class="num">Running</th></tr></thead><tbody>'+rows.slice(0,200).map(t=>'<tr><td>'+new Date(t.date).toLocaleDateString('en-PK')+' '+new Date(t.date).toLocaleTimeString('en-PK',{hour:'2-digit',minute:'2-digit'})+'</td><td><span class="pill '+(t.type==='SALE'?'green':t.type==='PURCHASE'?'orange':'red')+'">'+t.type+'</span></td><td>'+esc(t.ref)+'</td><td>'+esc(t.party)+'</td><td class="num" style="color:#059669">'+fmt(t.inAmt)+'</td><td class="num" style="color:#DC2626">'+fmt(t.outAmt)+'</td><td class="num"><b>'+fmt(t.running)+'</b></td></tr>').join('')+'</tbody></table>':'<div class="empty">No transactions.</div>';window._TX=rows}catch(e){if($('transactionsTable'))$('transactionsTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
window.setTxFilter=(type,btn)=>{TX_FILTER.type=type;document.querySelectorAll('[data-tx]').forEach(b=>b.classList.remove('active'));if(btn)btn.classList.add('active');loadTransactions()};
window.exportTransactions=()=>{const rows=window._TX||[];let csv='Date,Type,Ref,Party,In,Out,Running\n';rows.forEach(t=>csv+=t.date+','+t.type+',"'+t.ref+'","'+t.party+'",'+t.inAmt+','+t.outAmt+','+t.running+'\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='Transactions_'+Date.now()+'.csv';a.click();toast('Exported!','success')};
// =====================================================
// REPORTS & P&L - FULLY WORKING
// =====================================================
async function runReport(){const type=$('reportType')?.value||'pl';const from=$('reportFrom')?.value||bmTodayISO().slice(0,7)+'-01';const to=$('reportTo')?.value||bmTodayISO();const q=($('reportSearch')?.value||'').trim().toLowerCase();try{const [sales,items,purch,exps]=await Promise.all([supabase.from('sales').select('id,total,paid,balance,created_at,customer_name').gte('created_at',from).lte('created_at',to+'T23:59:59'),supabase.from('sale_items').select('sale_id,product_id,quantity,unit_price,line_total').gte('created_at',from).lte('created_at',to+'T23:59:59').limit(5000),supabase.from('purchases').select('total,paid,created_at').gte('created_at',from).lte('created_at',to+'T23:59:59'),supabase.from('expenses').select('amount,category,created_at').gte('created_at',from).lte('created_at',to+'T23:59:59')]);let sList=sales.data||[];if(q)sList=sList.filter(s=>(s.customer_name||'').toLowerCase().includes(q));const revenue=sList.reduce((a,s)=>a+Number(s.total||0),0);const prodIds=[...new Set((items.data||[]).map(i=>i.product_id).filter(Boolean))];let costMap={};if(prodIds.length){const{data:prods}=await supabase.from('products').select('id,purchase_price').in('id',prodIds);(prods||[]).forEach(pp=>costMap[pp.id]=Number(pp.purchase_price||0))}let cogs=0;(items.data||[]).forEach(it=>{if(sList.some(s=>s.id===it.sale_id))cogs+=(costMap[it.product_id]||Number(it.unit_price||0)*0.85)*Number(it.quantity||1)});const gross=revenue-cogs;const expTotal=(exps.data||[]).reduce((a,e)=>a+Number(e.amount||0),0);const purchTotal=(purch.data||[]).reduce((a,p)=>a+Number(p.total||0),0);const net=gross-expTotal;if($('plSummary'))$('plSummary').innerHTML='<div class="stats-grid"><div class="stat"><div class="stat-icon blue">R</div><div><strong>'+fmt(revenue)+'</strong><small>Total Revenue</small></div></div><div class="stat"><div class="stat-icon orange">C</div><div><strong>'+fmt(cogs)+'</strong><small>COGS</small></div></div><div class="stat"><div class="stat-icon green">G</div><div><strong>'+fmt(gross)+'</strong><small>Gross Profit</small></div></div><div class="stat"><div class="stat-icon red">E</div><div><strong>'+fmt(expTotal)+'</strong><small>Expenses</small></div></div><div class="stat"><div class="stat-icon purple">N</div><div><strong style="color:'+(net>=0?'#059669':'#DC2626')+'">'+fmt(net)+'</strong><small>Net Profit / Loss</small></div></div><div class="stat"><div class="stat-icon teal">P</div><div><strong>'+fmt(purchTotal)+'</strong><small>Purchases</small></div></div></div>';const out=$('reportOutput');if(out){if(type==='sales')out.innerHTML='<h4>Sales Report ('+sList.length+' sales)</h4><table class="data"><thead><tr><th>Invoice</th><th>Customer</th><th class="num">Total</th><th class="num">Paid</th><th class="num">Balance</th><th>Date</th></tr></thead><tbody>'+sList.map(s=>'<tr><td>'+esc(s.invoice_no||'')+'</td><td>'+esc(s.customer_name||'')+'</td><td class="num">'+fmt(s.total)+'</td><td class="num">'+fmt(s.paid)+'</td><td class="num">'+fmt(s.balance)+'</td><td>'+new Date(s.created_at).toLocaleDateString('en-PK')+'</td></tr>').join('')+'</tbody></table>';else if(type==='expenses')out.innerHTML='<h4>Expenses Report</h4><table class="data"><thead><tr><th>Category</th><th>Description</th><th class="num">Amount</th><th>Date</th></tr></thead><tbody>'+((exps.data||[]).map(e=>'<tr><td>'+esc(e.category||'')+'</td><td>'+esc(e.description||'')+'</td><td class="num">'+fmt(e.amount)+'</td><td>'+new Date(e.created_at).toLocaleDateString('en-PK')+'</td></tr>').join('')||'<tr><td colspan="4">No expenses</td></tr>')+'</tbody></table>';else out.innerHTML='<h4>P&L Summary</h4><table class="data"><tbody><tr><td>Revenue</td><td class="num"><b>'+fmt(revenue)+'</b></td></tr><tr><td>COGS</td><td class="num">'+fmt(cogs)+'</td></tr><tr><td>Gross Profit</td><td class="num"><b>'+fmt(gross)+'</b></td></tr><tr><td>Expenses</td><td class="num">'+fmt(expTotal)+'</td></tr><tr><td><b>Net Profit / Loss</b></td><td class="num"><b style="color:'+(net>=0?'#059669':'#DC2626')+'">'+fmt(net)+'</b></td></tr><tr><td>Purchases (Stock In)</td><td class="num">'+fmt(purchTotal)+'</td></tr></tbody></table>'}window._REPORT={revenue,cogs,gross,expTotal,net,from,to};await logActivity('VIEW','reports','Report: '+type+' '+from+' to '+to)}catch(e){if($('reportOutput'))$('reportOutput').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
$('btnRunReport')?.addEventListener('click',runReport);$('btnPrintReport')?.addEventListener('click',()=>{const r=window._REPORT;if(!r)return toast('Pehle report run karo','error');printA4Premium({invoice:'REPORT-'+r.from+' to '+r.to,total:r.revenue,paid:r.revenue,balance:0,customer:'P&L Report',items:[{product_name:'Revenue',quantity:1,unit_price:r.revenue,line_total:r.revenue},{product_name:'COGS',quantity:1,unit_price:r.cogs,line_total:r.cogs},{product_name:'Gross Profit',quantity:1,unit_price:r.gross,line_total:r.gross},{product_name:'Expenses',quantity:1,unit_price:r.expTotal,line_total:r.expTotal},{product_name:'Net Profit/Loss',quantity:1,unit_price:r.net,line_total:r.net}]},'sale')});

// =====================================================
// STAFF & LOGS (SETTINGS MODULE) - FULLY WORKING
// =====================================================
let STAFF_TABLE='staff_members',ALL_STAFF=[];
async function detectStaffTable(){for(const t of ['staff_members','staff']){const{error}=await supabase.from(t).select('id').limit(1);if(!error){STAFF_TABLE=t;return t}}return STAFF_TABLE}
async function loadStaff(){await detectStaffTable();try{const{data,error}=await supabase.from(STAFF_TABLE).select('*').order('created_at',{ascending:false});if(error)throw error;ALL_STAFF=data||[];const t=$('staffTable');if(t)t.innerHTML=ALL_STAFF.length?'<table class="data"><thead><tr><th>Staff</th><th>Staff ID</th><th>Role</th><th>Username</th><th>Can Edit</th><th>Can Delete</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+ALL_STAFF.map(st=>'<tr><td><b>'+esc(st.name||'-')+'</b></td><td>'+esc(st.staff_id||'-')+'</td><td><span class="pill blue">'+esc(st.role||'Cashier')+'</span></td><td><code>'+esc(st.username||'')+'</code></td><td>'+(st.can_edit?'Yes':'No')+'</td><td>'+(st.can_delete?'Yes':'No')+'</td><td><span class="pill '+(st.is_active!==false?'green':'red')+'">'+(st.is_active!==false?'Active':'Inactive')+'</span></td><td><button class="btn btn-sm" onclick="window.editStaffDash(\''+st.id+'\')">Edit</button> <button class="btn btn-sm btn-danger" onclick="window.deleteStaffDash(\''+st.id+'\')">Del</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">Koi staff nahi. Super Admin se staff banao, ya neeche Add Staff se banao.</div>'}catch(e){if($('staffTable'))$('staffTable').innerHTML='<div class="empty">Staff table nahi mili: '+esc(e.message)+'<br>Super Admin se Staff Table SQL run karo.</div>'}}
async function loadLogs(){try{const{data}=await supabase.from('activity_log').select('*').order('created_at',{ascending:false}).limit(200);const t=$('logsTable');if(!t)return;t.innerHTML=(data||[]).length?'<table class="data"><thead><tr><th>Time</th><th>Staff</th><th>Action</th><th>Module</th><th>Details</th></tr></thead><tbody>'+data.map(l=>'<tr><td><small>'+new Date(l.created_at).toLocaleString('en-PK')+'</small></td><td>'+esc(l.staff_name||l.staff_id||'-')+'</td><td><span class="pill blue">'+esc(l.action||'')+'</span></td><td>'+esc(l.module||'')+'</td><td>'+esc(l.details||'')+'</td></tr>').join('')+'</tbody></table>':'<div class="empty">No logs.</div>'}catch(e){if($('logsTable'))$('logsTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
window.editStaffDash=async id=>{const st=ALL_STAFF.find(x=>x.id===id);if(!st)return;const body='<div class="form-grid"><div class="field"><label>Name</label><input id="stName" value="'+esc(st.name||'')+'"></div><div class="field"><label>Role</label><select id="stRole"><option>Cashier</option><option>Manager</option><option>Admin</option><option>Repair</option><option>Viewer</option></select></div><div class="field"><label>Username</label><input id="stUser" value="'+esc(st.username||'')+'"></div><div class="field"><label>Password</label><input id="stPass" value="'+esc(st.password||'')+'"></div><div class="field"><label>Can Edit</label><select id="stEdit"><option value="true">Yes</option><option value="false">No</option></select></div><div class="field"><label>Can Delete</label><select id="stDel"><option value="true">Yes</option><option value="false">No</option></select></div><div class="field"><label>Active</label><select id="stAct"><option value="true">Active</option><option value="false">Inactive</option></select></div></div>';openModal('Edit Staff',body,async()=>{const payload={name:$('stName').value.trim(),role:$('stRole').value,username:$('stUser').value.trim(),password:$('stPass').value.trim(),can_edit:$('stEdit').value==='true',can_delete:$('stDel').value==='true',is_active:$('stAct').value==='true'};await supabase.from(STAFF_TABLE).update(payload).eq('id',id);closeModal();toast('Saved','success');loadStaff()},'Save');setTimeout(()=>{if($('stRole'))$('stRole').value=st.role||'Cashier';if($('stEdit'))$('stEdit').value=String(!!st.can_edit);if($('stDel'))$('stDel').value=String(!!st.can_delete);if($('stAct'))$('stAct').value=String(st.is_active!==false)},100)};
window.deleteStaffDash=async id=>{if(!checkPermission('delete'))return;if(!confirm('Delete staff?'))return;await supabase.from(STAFF_TABLE).delete().eq('id',id);toast('Deleted');loadStaff()};
window.addStaffDash=()=>{const body='<div class="form-grid"><div class="field"><label>Staff Name *</label><input id="stName" placeholder="Ali Khan"></div><div class="field"><label>Staff ID *</label><input id="stCode" placeholder="02"></div><div class="field"><label>Username *</label><input id="stUser" placeholder="ali"></div><div class="field"><label>Password *</label><input id="stPass" placeholder="12345"></div><div class="field"><label>Role</label><select id="stRole"><option>Cashier</option><option>Manager</option><option>Admin</option><option>Repair</option><option>Viewer</option></select></div></div><p style="font-size:12px;color:var(--muted)">Staff Super Admin se bhi ban sakta hai. Yahan se banaya hua staff isi shop ka hoga.</p>';openModal('Add Staff (Is Shop Ka)',body,async()=>{const payload={shop_id:SHOP_ID,name:$('stName').value.trim(),staff_id:$('stCode').value.trim(),username:$('stUser').value.trim(),password:$('stPass').value.trim(),role:$('stRole').value,can_edit:true,can_delete:false,is_active:true};if(!payload.name||!payload.staff_id||!payload.username||!payload.password)throw new Error('Sab fields required');const{error}=await supabase.from(STAFF_TABLE).insert(payload);if(error)throw new Error(error.message);closeModal();toast('Staff created!','success');loadStaff()},'Create Staff')};
