window.BM={lowStock:()=>ALL_PRODUCTS.filter(p=>Number(p.quantity||0)<=Number(p.min_stock||5)),stockValue:()=>ALL_PRODUCTS.reduce((a,p)=>a+Number(p.quantity||0)*Number(p.purchase_price||0),0),stockSaleValue:()=>ALL_PRODUCTS.reduce((a,p)=>a+Number(p.quantity||0)*Number(p.sale_price||0),0),todaySales:async()=>{const{data}=await supabase.from('sales').select('total').gte('created_at',bmTodayISO());return (data||[]).reduce((a,s)=>a+Number(s.total||0),0)},udharTotal:async()=>{const{data}=await supabase.from('sales').select('balance').gt('balance',0);return (data||[]).reduce((a,s)=>a+Number(s.balance||0),0)},margin:(buy,sale)=>sale-buy,marginPct:(buy,sale)=>buy?Math.round((sale-buy)/buy*100):0,profitPerUnit:(buy,sale)=>sale-buy,quickWhatsApp:(phone,msg)=>window.open('https://wa.me/92'+String(phone||'').replace(/\D/g,'').slice(-10)+'?text='+encodeURIComponent(msg),'_blank'),copy:(t)=>copyToClipboard(t),printUdharAll:()=>window.printAllUdhar&&window.printAllUdhar(),exportAll:async()=>{const tables=['products','sales','customers','suppliers','expenses','repairs','purchases'];const out={};for(const t of tables){const{data}=await supabase.from(t).select('*').limit(5000);out[t]=data||[]}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));a.download='BM_Backup_'+Date.now()+'.json';a.click();toast('Backup exported!','success')},searchEverything:(q)=>globalSearch(q),focusPOS:()=>focusPOS(),dailyPL:()=>loadDailyPL(),openShortcuts:()=>showShortcutHelp(),calcProfit:(rev,cogs,exp)=>rev-cogs-exp};
