function injectMissingUI(){if(!document.getElementById('expCatChart')){const box=$('expensesTable')?.closest('.card');if(box){const d=document.createElement('div');d.id='expCatChart';d.style.marginBottom='16px';box.prepend(d)}}if(!document.getElementById('txIn')){const box=$('transactionsTable')?.closest('.card');if(box){const d=document.createElement('div');d.className='stats-grid';d.innerHTML='<div class="stat"><div class="stat-icon green">IN</div><div><strong id="txIn">PKR 0</strong><small>Total In</small></div></div><div class="stat"><div class="stat-icon red">OUT</div><div><strong id="txOut">PKR 0</strong><small>Total Out</small></div></div><div class="stat"><div class="stat-icon purple">NET</div><div><strong id="txNet">PKR 0</strong><small>Net</small></div></div>';box.prepend(d)}}const staffBox=$('staffTable')?.closest('.card');if(staffBox&&!document.getElementById('btnAddStaffDash')){const btn=document.createElement('button');btn.id='btnAddStaffDash';btn.className='btn btn-primary';btn.style.marginBottom='12px';btn.textContent='+ Add Staff (Is Shop)';btn.onclick=()=>window.addStaffDash();staffBox.prepend(btn)}const logsBox=$('logsTable')?.closest('.card');if(logsBox&&!document.getElementById('btnRefreshLogs')){const btn=document.createElement('button');btn.id='btnRefreshLogs';btn.className='btn btn-ghost';btn.style.marginBottom='12px';btn.textContent='Refresh Logs';btn.onclick=()=>{loadLogs();loadStaff()};logsBox.prepend(btn)}const txBox=$('transactionsTable')?.closest('.card');if(txBox&&!document.getElementById('txToolbar')){const d=document.createElement('div');d.id='txToolbar';d.className='toolbar';d.style.marginBottom='12px';d.innerHTML='<div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-sm active" data-tx onclick="window.setTxFilter(\'all\',this)">All</button><button class="btn btn-sm" data-tx onclick="window.setTxFilter(\'SALE\',this)">Sales</button><button class="btn btn-sm" data-tx onclick="window.setTxFilter(\'PURCHASE\',this)">Purchases</button><button class="btn btn-sm" data-tx onclick="window.setTxFilter(\'EXPENSE\',this)">Expenses</button><button class="btn btn-sm btn-primary" onclick="window.exportTransactions()">Export CSV</button></div>';txBox.prepend(d)}const repBox=$('reportOutput')?.closest('.card');if(repBox&&!document.getElementById('reportToolbar')){const d=document.createElement('div');d.id='reportToolbar';d.style.marginBottom='12px';d.innerHTML='<div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-sm btn-primary" onclick="runReport()">Run Report</button><button class="btn btn-sm" onclick="window.exportDailyPL && window.exportDailyPL()">Export Daily P&L</button></div>';repBox.prepend(d)}}
async function init(){await loadShopSettings();injectMissingUI();document.querySelectorAll('.module').forEach(m=>attachEnterNavigation(m));attachEnterNavigation(document);await loadOverview();await loadSaleProducts();await loadProducts();await loadStaff();await loadLogs();loadNotifs();setTimeout(()=>{if(document.querySelector('#module-overview.active'))focusPOS()},500)}
init();

window.toggleFocusMode=()=>{document.body.classList.toggle('focus-mode');toast(document.body.classList.contains('focus-mode')?'Focus Mode ON - sirf POS dikhega':'Focus Mode OFF','info')};
